sources.infra/aws/database-audit/main.tf:
terraform {
  required_version = "= 1.11.2"
  backend "s3" {}
  required_providers {
    aws = { source = "hashicorp/aws", version = "= 6.50.0" }
  }
}
variable "account_id" {
  type    = string
  default = "564503811353"
}
variable "region" {
  type    = string
  default = "us-east-1"
}
variable "environment" { type = string }
variable "source_commit" { type = string }
variable "projection" {
  type = object({ source_kms_arn = string, destination_kms_arn = string, run_task_roles = map(string) })
}
variable "foundation_authority" {
  type    = object({ plan_role_id = string, apply_role_id = string })
  default = null
}
locals {
  tags             = { Project = "CyberCoach", Environment = var.environment, ManagedBy = "OpenTofu", BillingOwner = "Mac Clark", ManagedRoot = "database-audit", SourceCommit = var.source_commit }
  foundation_roles = { for op in ["plan", "apply"] : op => "arn:aws:iam::564503811353:role/platform-foundation/database-audit/${var.environment}/cybercoach-${var.environment}-foundation-database-audit-${op}" }
}
provider "aws" {
  region              = "us-east-1"
  allowed_account_ids = ["564503811353"]
  default_tags { tags = local.tags }
}
data "aws_caller_identity" "current" {}
data "aws_iam_role" "launch_inspect" {
  name = "cybercoach-${var.environment}-database-inspect"
}
data "aws_iam_role" "launch_initialize" {
  name = "cybercoach-${var.environment}-database-initialize"
}
data "aws_iam_role" "launch_initialize_recovery" {
  name = "cybercoach-${var.environment}-database-initialize-recovery"
}
data "aws_iam_role" "launch_recovery" {
  name = "cybercoach-${var.environment}-database-recovery"
}
data "aws_iam_role" "launch_native" {
  count = contains(keys(var.projection.run_task_roles), "arn:aws:iam::564503811353:role/platform/dev/cybercoach-dev-database-native") ? 1 : 0
  name  = "cybercoach-dev-database-native"
}
locals {
  launch_roles = merge({
    "arn:aws:iam::564503811353:role/platform/${var.environment}/cybercoach-${var.environment}-database-inspect"             = data.aws_iam_role.launch_inspect
    "arn:aws:iam::564503811353:role/platform/${var.environment}/cybercoach-${var.environment}-database-initialize"          = data.aws_iam_role.launch_initialize
    "arn:aws:iam::564503811353:role/platform/${var.environment}/cybercoach-${var.environment}-database-initialize-recovery" = data.aws_iam_role.launch_initialize_recovery
    "arn:aws:iam::564503811353:role/platform/${var.environment}/cybercoach-${var.environment}-database-recovery"            = data.aws_iam_role.launch_recovery
  }, { for r in data.aws_iam_role.launch_native : r.arn => r })
}
resource "terraform_data" "guard" {
  input = { source = var.source_commit, projection = var.projection }
  lifecycle {
    precondition {
      condition     = var.account_id == "564503811353" && var.region == "us-east-1" && contains(["dev", "production"], var.environment) && can(regex("^[a-f0-9]{40}$", var.source_commit)) && data.aws_caller_identity.current.account_id == "564503811353"
      error_message = "Only the exact CyberCoach account/region/environment and reviewed source are supported."
    }
    precondition {
      condition = var.foundation_authority == null ? (
        data.aws_caller_identity.current.arn == "arn:aws:iam::564503811353:user/mclark" && data.aws_caller_identity.current.user_id == "AIDAJ32SZWTZ33TRLYXEU"
        ) : try(length(distinct([var.foundation_authority.plan_role_id, var.foundation_authority.apply_role_id])) == 2 && alltrue([for id in [var.foundation_authority.plan_role_id, var.foundation_authority.apply_role_id] : can(regex("^AROA[A-Z0-9]{17}$", id))]) && anytrue([for op in ["plan", "apply"] : (
          startswith(data.aws_caller_identity.current.arn, "arn:aws:sts::564503811353:assumed-role/cybercoach-${var.environment}-foundation-database-audit-${op}/") && data.aws_caller_identity.current.user_id == "${var.foundation_authority["${op}_role_id"]}:${element(reverse(split("/", data.aws_caller_identity.current.arn)), 0)}"
      )]), false)
      error_message = "Only the original operator or installed canonical immutable foundation pair may provision this independent state."
    }
    precondition {
      condition     = alltrue([for arn, role in local.launch_roles : role.arn == arn && role.unique_id == var.projection.run_task_roles[arn]])
      error_message = "Projection cannot admit recreated or substituted database launch identities."
    }
  }
}
module "projection" {
  source                         = "../modules/database-audit-projection"
  reserved_concurrent_executions = var.environment == "dev" ? 8 : 2
  environment                    = var.environment
  source_kms_arn                 = var.projection.source_kms_arn
  destination_kms_arn            = var.projection.destination_kms_arn
  run_task_roles                 = var.projection.run_task_roles
  tags                           = local.tags
  depends_on                     = [terraform_data.guard]
}
output "audit_projection" { value = module.projection.contract }

sources.infra/aws/modules/audit-foundation/recei:
locals {
  mac_operator_arn    = "arn:aws:iam::564503811353:user/mclark"
  mac_operator_caller = var.governance_profile == "operator-managed-v1" && data.aws_caller_identity.current.arn == local.mac_operator_arn && data.aws_caller_identity.current.user_id == "AIDAJ32SZWTZ33TRLYXEU"

  records = var.source_purpose == "records" && var.records_destination != null ? { records = {
    bucket_name               = var.records_destination.bucket_name
    retention_days            = var.records_destination.retention_days
    noncurrent_retention_days = var.records_destination.noncurrent_retention_days
    object_lock_days          = var.records_destination.object_lock_days
    access_log_receiver = {
      bucket_name               = var.records_destination.access_log_receiver.bucket_name
      retention_days            = var.records_destination.access_log_receiver.retention_days
      noncurrent_retention_days = var.records_destination.access_log_receiver.noncurrent_retention_days
    }
    log_group_name            = var.records_destination.log_group_name
    cloudwatch_retention_days = var.records_destination.cloudwatch_retention_days
    alarm_topic_name          = var.records_destination.alarm_topic_name
    alarm_subscriptions       = var.records_destination.alarm_subscriptions
  } } : {}
  receivers = merge({ source = {
    bucket_name               = var.access_log_receiver.bucket_name
    retention_days            = var.access_log_receiver.retention_days
    noncurrent_retention_days = var.access_log_receiver.noncurrent_retention_days
    } }, {
    for k, r in local.records : "trail" => r.access_log_receiver
  })
  source_policy_parameters = merge({
    account_id         = var.account_id
    environment        = var.environment
    receiver_bucket    = var.access_log_receiver.bucket_name
    receiver_custodian = var.custodian_role_arn
    }, var.source_purpose == "bootstrap" ? {
    state_bucket_name = lookup(var.source_buckets, "state", "")
    plan_bucket_name  = lookup(var.source_buckets, "plan", "")
    } : {
    bucket_name = lookup(var.source_buckets, "records", "")
  })
  # Legacy templates retain their exact statement/array order. Only the explicit
  # operator records variant adds resource-local Mac administration.
  legacy_access_log_policy = jsonencode(jsondecode(templatefile(
    var.source_purpose == "bootstrap" ? "${path.module}/../../bootstrap/contracts/access-log-policy.json.tftpl" : "${path.module}/../records/contracts/${var.governance_profile == "operator-managed-v1" ? "access-log-policy-operator" : "access-log-policy"}.json.tftpl",
    { for k, v in local.source_policy_parameters : k => substr(jsonencode(v), 1, length(jsonencode(v)) - 2) }
  )))
  required_access_log_policy = var.custody_coverage == null ? local.legacy_access_log_policy : jsonencode(merge(jsondecode(local.legacy_access_log_policy), {
    Statement = concat(jsondecode(local.legacy_access_log_policy).Statement, local.custody_log_statements)
  }))
  receiver_policies = merge({ source = local.required_access_log_policy }, {
    for k, r in local.records : "trail" => jsonencode({
      Version = "2012-10-17"
      Statement = concat(var.governance_profile == "operator-managed-v1" ? [{ Sid = "MacOperatorBucketAdministration", Effect = "Allow", Principal = { AWS = local.mac_operator_arn }, Action = ["s3:GetBucket*", "s3:ListBucket*", "s3:PutBucket*", "s3:GetEncryptionConfiguration", "s3:PutEncryptionConfiguration", "s3:GetLifecycleConfiguration", "s3:PutLifecycleConfiguration"], Resource = "arn:aws:s3:::${r.access_log_receiver.bucket_name}" }] : [], [
        { Sid = "DeliveryTrailAccess", Effect = "Allow", Principal = { Service = "logging.s3.amazonaws.com" }, Action = "s3:PutObject", Resource = "arn:aws:s3:::${r.access_log_receiver.bucket_name}/cybercoach/${var.environment}/trail/*", Condition = { ArnEquals = { "aws:SourceArn" = "arn:aws:s3:::${r.bucket_name}" }, StringEquals = { "aws:SourceAccount" = var.account_id } } },
        { Sid = "TLSOnly", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = ["arn:aws:s3:::${r.access_log_receiver.bucket_name}", "arn:aws:s3:::${r.access_log_receiver.bucket_name}/*"], Condition = { Bool = { "aws:SecureTransport" = "false", "aws:PrincipalIsAWSService" = "false" } } },
        { Sid = "IndependentCustody", Effect = "Deny", Principal = "*", Action = ["s3:Put*", "s3:Delete*", "s3:Replicate*", "s3:RestoreObject", "s3:BypassGovernanceRetention"], Resource = ["arn:aws:s3:::${r.access_log_receiver.bucket_name}", "arn:aws:s3:::${r.access_log_receiver.bucket_name}/*"], Condition = { ArnNotEquals = { "aws:PrincipalArn" = jsondecode(var.governance_profile == "operator-managed-v1" ? jsonencode([var.custodian_role_arn, local.mac_operator_arn]) : jsonencode(var.custodian_role_arn)) }, Bool = { "aws:PrincipalIsAWSService" = "false" } } }
      ])
    })
  })
}

data "aws_caller_identity" "current" {}
data "aws_iam_session_context" "current" {
  count = var.governance_profile == "operator-managed-v1" && !startswith(data.aws_caller_identity.current.arn, "arn:aws:sts::") ? 0 : 1
  arn   = data.aws_caller_identity.current.arn
}

# AWS requires SSE-S3 and no receiver logging/Object Lock. Preserve actual
# scanner findings; this is not an exemption or a claim of CMK encryption.
resource "aws_s3_bucket" "receiver" {
  tags = local.cost_allocation_tags

  for_each            = local.receivers
  bucket              = each.value.bucket_name
  force_destroy       = false
  object_lock_enabled = false
  lifecycle {
    prevent_destroy = true
    precondition {
      condition     = (var.custody_coverage == null || local.mac_operator_caller) && data.aws_caller_identity.current.account_id == var.account_id && (local.mac_operator_caller || try(contains([var.plan_role_arn, var.custodian_role_arn], data.aws_iam_session_context.current[0].issuer_arn), false))
      error_message = "Use the exact canonical audit roles, or the fixed Mac identity in the explicit operator profile; IAM separately restricts mutation."
    }
  }
}
resource "aws_s3_bucket_ownership_controls" "receiver" {
  for_each = local.receivers
  bucket   = aws_s3_bucket.receiver[each.key].id
  rule { object_ownership = "BucketOwnerEnforced" }
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_public_access_block" "receiver" {
  for_each                = local.receivers
  bucket                  = aws_s3_bucket.receiver[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_versioning" "receiver" {
  for_each = local.receivers
  bucket   = aws_s3_bucket.receiver[each.key].id
  versioning_configuration { status = "Enabled" }
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_server_side_encryption_configuration" "receiver" {
  for_each = local.receivers
  bucket   = aws_s3_bucket.receiver[each.key].id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "AES256" }
  }
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_request_payment_configuration" "receiver" {
  for_each = local.receivers
  bucket   = aws_s3_bucket.receiver[each.key].id
  payer    = "BucketOwner"
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_lifecycle_configuration" "receiver" {
  for_each = local.receivers
  bucket   = aws_s3_bucket.receiver[each.key].id
  rule {
    id     = "approved-access-log-expiry"
    status = "Enabled"
    filter { prefix = "" }
    expiration { days = each.value.retention_days }
    noncurrent_version_expiration { noncurrent_days = each.value.noncurrent_retention_days }
  }
  depends_on = [aws_s3_bucket_versioning.receiver]
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_policy" "receiver" {
  for_each = local.receivers
  bucket   = aws_s3_bucket.receiver[each.key].id
  policy   = local.receiver_policies[each.key]
  depends_on = [aws_s3_bucket_public_access_block.receiver,
  aws_s3_bucket_ownership_controls.receiver]
  lifecycle { prevent_destroy = true }
}

sources.infra/aws/modules/database-audit-project:
# Exact account/environment delivery only. This module never owns the source
# trail, either log group, an archive, a CMK, or an alarm subscription.
terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "= 6.50.0" }
  }
}
variable "environment" { type = string }
variable "reserved_concurrent_executions" {
  type     = number
  default  = 2
  nullable = false
  validation {
    condition     = contains([2, 8], var.reserved_concurrent_executions)
    error_message = "Projection reservation must be the existing 2 or selected DEV 8."
  }
}
variable "source_kms_arn" { type = string }
variable "destination_kms_arn" { type = string }
variable "run_task_roles" { type = map(string) }
variable "tags" { type = map(string) }
locals {
  name            = "cybercoach-${var.environment}-database-audit-projection"
  source          = "/platform/audit/${var.environment}/records"
  destination     = "/cybercoach/${var.environment}/operator-cloudtrail"
  stream          = "projection/database-recovery"
  source_arn      = "arn:aws:logs:us-east-1:564503811353:log-group:${local.source}"
  destination_arn = "arn:aws:logs:us-east-1:564503811353:log-group:${local.destination}"
  filter          = "cybercoach-${var.environment}-database-recovery"
  alarm           = "cybercoach-${var.environment}-database-audit-delivery"
  topic           = "arn:aws:sns:us-east-1:564503811353:platform-audit-${var.environment}-records"
  role_path       = "/platform/${var.environment}/"
  allowed_roles   = toset(concat([for op in ["inspect", "initialize", "initialize-recovery", "recovery"] : "arn:aws:iam::564503811353:role/platform/${var.environment}/cybercoach-${var.environment}-database-${op}"], var.environment == "dev" ? ["arn:aws:iam::564503811353:role/platform/dev/cybercoach-dev-database-native"] : []))
  config          = { environment = var.environment, run_task_roles = var.run_task_roles }
  write_policy = jsonencode({ Version = "2012-10-17", Statement = [{
    Effect = "Allow", Action = ["logs:PutLogEvents"], Resource = "${local.destination_arn}:log-stream:${local.stream}"
  }] })
  metrics = {
    errors    = { namespace = "AWS/Lambda", name = "Errors", dimensions = { FunctionName = local.name } }
    throttles = { namespace = "AWS/Lambda", name = "Throttles", dimensions = { FunctionName = local.name } }
    dropped   = { namespace = "AWS/Lambda", name = "AsyncEventsDropped", dimensions = { FunctionName = local.name } }
    delivery  = { namespace = "AWS/Logs", name = "DeliveryErrors", dimensions = { LogGroupName = local.source, DestinationType = "Lambda", FilterName = local.filter } }
    pressure  = { namespace = "AWS/Logs", name = "DeliveryThrottling", dimensions = { LogGroupName = local.source, DestinationType = "Lambda", FilterName = local.filter } }
  }
}
data "aws_caller_identity" "current" {}
data "aws_cloudwatch_log_group" "source" {
  name = local.source
  lifecycle {
    postcondition {
      condition     = self.arn == local.source_arn && self.kms_key_id == var.source_kms_arn && self.retention_in_days >= 365 && self.deletion_protection_enabled && self.log_group_class == "STANDARD"
      error_message = "Shared source must be the exact existing encrypted, protected, STANDARD log group with at least 365 days retention."
    }
  }
}
data "aws_cloudwatch_log_group" "destination" {
  name = local.destination
  lifecycle {
    postcondition {
      condition     = self.arn == local.destination_arn && self.kms_key_id == var.destination_kms_arn && self.retention_in_days >= 365 && self.deletion_protection_enabled && self.log_group_class == "STANDARD"
      error_message = "The original database destination, CMK and retention must remain installed."
    }
  }
}
resource "terraform_data" "guard" {
  input = local.config
  lifecycle {
    precondition {
      condition     = var.environment == "dev" || var.reserved_concurrent_executions == 2
      error_message = "Only DEV may use the selected reservation of 8; non-DEV remains 2."
    }
    precondition {
      condition = (
        contains(["dev", "production"], var.environment) && data.aws_caller_identity.current.account_id == "564503811353" &&
        alltrue([for arn in [var.source_kms_arn, var.destination_kms_arn] : can(regex("^arn:aws:kms:us-east-1:564503811353:key/[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$", arn))]) && var.source_kms_arn != var.destination_kms_arn &&
        length(setsubtract(toset(keys(var.run_task_roles)), local.allowed_roles)) == 0 &&
        length(var.run_task_roles) >= 4 && length(var.run_task_roles) <= (var.environment == "dev" ? 5 : 4) &&
        alltrue([for op in ["inspect", "initialize", "initialize-recovery", "recovery"] : contains(keys(var.run_task_roles), "arn:aws:iam::564503811353:role/platform/${var.environment}/cybercoach-${var.environment}-database-${op}")]) &&
        alltrue([for id in values(var.run_task_roles) : can(regex("^AROA[A-Z0-9]{17}$", id))]) && length(distinct(values(var.run_task_roles))) == length(var.run_task_roles) &&
        var.tags.Project == "CyberCoach" && var.tags.Environment == var.environment && var.tags.ManagedBy == "OpenTofu" && var.tags.BillingOwner == "Mac Clark"
      )
      error_message = "Projection requires the canonical environment, distinct actual CMKs, original selected role IDs and exact ownership tags."
    }
  }
}
resource "aws_cloudwatch_log_stream" "destination" {
  name           = local.stream
  log_group_name = data.aws_cloudwatch_log_group.destination.name
  depends_on     = [terraform_data.guard]
  lifecycle { prevent_destroy = true }
}
resource "aws_iam_policy" "delivery" {
  name   = "${local.name}-boundary"
  path   = local.role_path
  policy = local.write_policy
  tags   = var.tags
  lifecycle { prevent_destroy = true }
}
resource "aws_iam_role" "delivery" {
  name                 = local.name
  path                 = local.role_path
  permissions_boundary = aws_iam_policy.delivery.arn
  max_session_duration = 3600
  assume_role_policy = jsonencode({ Version = "2012-10-17", Statement = [{
    Effect = "Allow", Principal = { Service = "lambda.amazonaws.com" }, Action = "sts:AssumeRole"
  }] })
  tags       = var.tags
  depends_on = [terraform_data.guard]
  lifecycle { prevent_destroy = true }
}
resource "aws_iam_role_policy" "delivery" {
  name   = "ExactDatabaseAuditDelivery"
  role   = aws_iam_role.delivery.id
  policy = local.write_policy
  lifecycle { prevent_destroy = true }
}
resource "aws_lambda_function" "delivery" {
  function_name                  = local.name
  role                           = aws_iam_role.delivery.arn
  handler                        = "delivery.handler"
  runtime                        = "python3.12"
  architectures                  = ["arm64"]
  filename                       = "${path.module}/delivery.zip"
  source_code_hash               = filebase64sha256("${path.module}/delivery.zip")
  timeout                        = 60
  memory_size                    = 256
  reserved_concurrent_executions = var.reserved_concurrent_executions
  environment { variables = { PROJECTION = jsonencode(local.config) } }
  # No application log permissions: the handler never logs payloads. Failure
  # detection uses service-produced Errors/Throttles/AsyncEventsDropped metrics.
  # It has no read permission on either audit group and no direct KMS permission.
  tags       = var.tags
  depends_on = [aws_iam_role_policy.delivery, aws_cloudwatch_log_stream.destination]
  lifecycle { prevent_destroy = true }
}
resource "aws_lambda_function_event_invoke_config" "delivery" {
  function_name                = aws_lambda_function.delivery.function_name
  maximum_event_age_in_seconds = 21600
  maximum_retry_attempts       = 2
  lifecycle { prevent_destroy = true }
}
resource "aws_lambda_permission" "source" {
  statement_id   = "ExactRecordsAuditSource"
  action         = "lambda:InvokeFunction"
  function_name  = aws_lambda_function.delivery.function_name
  principal      = "logs.us-east-1.amazonaws.com"
  source_account = "564503811353"
  source_arn     = "${local.source_arn}:*"
}
resource "aws_cloudwatch_log_subscription_filter" "source" {
  name            = local.filter
  log_group_name  = data.aws_cloudwatch_log_group.source.name
  destination_arn = aws_lambda_function.delivery.arn
  filter_pattern  = "{ ($.recipientAccountId = \"564503811353\") && ($.awsRegion = \"us-east-1\") && ((($.eventSource = \"ecs.amazonaws.com\") && ($.eventName = \"RunTask\")) || (($.eventSource = \"codebuild.amazonaws.com\") && ($.eventName = \"StartBuild\"))) }"
  depends_on      = [aws_lambda_permission.source, aws_lambda_function_event_invoke_config.delivery, aws_cloudwatch_metric_alarm.failure]
  lifecycle { prevent_destroy = true }
}
resource "aws_cloudwatch_metric_alarm" "failure" {
  alarm_name          = local.alarm
  alarm_description   = "Database recovery audit projection failed or throttled. Retain native trail until actual correlated delivery and notification proof; missing recovery events remain HOLD."
  evaluation_periods  = 1
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"
  alarm_actions       = [local.topic]
  ok_actions          = [local.topic]
  metric_query {
    id          = "failure"
    expression  = "SUM(METRICS())"
    label       = "Projection delivery failures"
    return_data = true
  }
  dynamic "metric_query" {
    for_each = local.metrics
    content {
      id          = metric_query.key
      return_data = false
      metric {
        namespace   = metric_query.value.namespace
        metric_name = metric_query.value.name
        dimensions  = metric_query.value.dimensions
        period      = 60
        stat        = "Sum"
      }
    }
  }
  tags = var.tags
  lifecycle { prevent_destroy = true }
}
output "contract" {
  value = {
    format              = "cybercoach-database-audit-projection-v1"
    environment         = var.environment
    source_group        = local.source
    source_kms_arn      = var.source_kms_arn
    destination_group   = local.destination
    destination_kms_arn = var.destination_kms_arn
    destination_stream  = local.stream
    role_arn            = aws_iam_role.delivery.arn
    role_id             = aws_iam_role.delivery.unique_id
    function_arn        = aws_lambda_function.delivery.arn
    package_sha256      = filesha256("${path.module}/delivery.zip")
    handler_sha256      = filesha256("${path.module}/delivery.py")
    alarm_arn           = aws_cloudwatch_metric_alarm.failure.arn
    config              = local.config
  }
}

sources.infra/aws/modules/origin-authentication/:
terraform {
  required_version = "= 1.11.2"
  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = "= 6.50.0"
      configuration_aliases = [aws.origin_custodian]
    }
  }
}
variable "account_id" {
  type = string
  validation {
    condition     = var.account_id == "564503811353"
    error_message = "Exact CyberCoach account required."
  }
}
variable "environment" {
  type = string
  validation {
    condition     = contains(["dev", "production"], var.environment)
    error_message = "Exact environment required."
  }
}
variable "secret_arn" {
  type = string
  validation {
    condition     = can(regex("^arn:aws:secretsmanager:us-east-1:${var.account_id}:secret:cybercoach/${var.environment}/origin-auth-[A-Za-z0-9]{6}$", var.secret_arn))
    error_message = "Exact existing environment origin credential metadata required."
  }
}
variable "secret_kms_key_arn" {
  type = string
  validation {
    condition     = can(regex("^arn:aws:kms:us-east-1:${var.account_id}:key/[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$", var.secret_kms_key_arn))
    error_message = "Exact same-account origin secret key required."
  }
}
variable "function_zip_path" { type = string }
variable "function_zip_sha256_base64" { type = string }
locals {
  name = "cybercoach-${var.environment}-origin-auth"
  cost_allocation_tags = {
    Project      = "CyberCoach"
    Environment  = var.environment
    ManagedBy    = "OpenTofu"
    BillingOwner = "Mac Clark"
  }
}
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
resource "aws_iam_role" "origin" {
  tags = local.cost_allocation_tags
  name = local.name
  path = "/cybercoach-origin-auth/${var.environment}/"
  assume_role_policy = jsonencode({ Version = "2012-10-17", Statement = [{
    Effect = "Allow", Action = "sts:AssumeRole", Principal = { Service = ["lambda.amazonaws.com", "edgelambda.amazonaws.com"] }
  }] })
  lifecycle { prevent_destroy = true }
}
resource "aws_iam_role_policy" "origin" {
  name = "exact-origin-credential-read"
  role = aws_iam_role.origin.id
  policy = jsonencode({ Version = "2012-10-17", Statement = [
    { Effect = "Allow", Action = ["secretsmanager:GetSecretValue"], Resource = [var.secret_arn] },
    { Effect = "Allow", Action = ["kms:Decrypt"], Resource = [var.secret_kms_key_arn], Condition = {
      StringEquals = { "kms:ViaService" = "secretsmanager.us-east-1.amazonaws.com", "kms:EncryptionContext:SecretARN" = var.secret_arn }
    } }
  ] })
}
resource "aws_lambda_function" "origin" {
  tags             = local.cost_allocation_tags
  function_name    = local.name
  role             = aws_iam_role.origin.arn
  runtime          = "nodejs22.x"
  handler          = "index.handler"
  architectures    = ["x86_64"]
  filename         = var.function_zip_path
  source_code_hash = var.function_zip_sha256_base64
  publish          = true
  timeout          = 5
  memory_size      = 128
  depends_on       = [aws_iam_role_policy.origin]
  lifecycle {
    prevent_destroy = true
    precondition {
      condition     = data.aws_caller_identity.current.account_id == var.account_id && data.aws_region.current.region == "us-east-1" && filebase64sha256(var.function_zip_path) == var.function_zip_sha256_base64
      error_message = "Exact account/us-east-1 and prepared archive digest required."
    }
  }
}
output "binding" {
  value = {
    distribution_arn     = var.distribution_arn
    account_id           = var.account_id
    environment          = var.environment
    function_version_arn = aws_lambda_function.origin.qualified_arn
    execution_role_arn   = aws_iam_role.origin.arn
    execution_role_id    = aws_iam_role.origin.unique_id
    secret_arn           = var.secret_arn
    runtime_mode         = "lambda-token-v1"
    runtime_secret_name  = "ORIGIN_AUTH_BINDING"
    custody_status       = "REQUIRES_EFFECTIVE_SCOPED_GOVERNANCE_AND_SECRET_READBACK"
  }
}

sources.infra/aws/modules/public-frontdoor/dev-s:
# Snapshot of only the source ACL's five host-independent IP allowances.
# Own these DEV copies; never attach, import or mutate the shared source ACL/sets.
# The separate general IPv6 whitelist is not a state-network IPv6 allocation.
locals {
  dev_network_snapshot = jsondecode(file("${path.module}/dev-state-network.json"))
  dev_network_sets     = var.dev_network_policy == null ? {} : local.dev_network_snapshot.sets
}

resource "aws_wafv2_ip_set" "dev_network" {
  provider           = aws.edge
  for_each           = local.dev_network_sets
  name               = "${local.name}-nonprod-${replace(each.key, "_", "-")}"
  description        = "DEV copy of ${each.value.source_name}: nonprod-global-20260925"
  scope              = "CLOUDFRONT"
  ip_address_version = each.value.ip_address_version
  addresses          = each.value.addresses
  tags               = merge({ Project = "CyberCoach", Environment = var.environment, AuthoritySHA256 = var.origin.authority_sha256 }, local.cost_allocation_tags)
}

output "dev_network_policy" {
  description = "Selected DEV snapshot and owned IP-set IDs/ARNs/membership for exact post-apply comparison; null in the unchanged default/production mode."
  value = var.dev_network_policy == null ? null : {
    policy_id            = var.dev_network_policy
    source_policy_sha256 = local.dev_network_snapshot.source_policy_sha256
    sets = { for key, value in aws_wafv2_ip_set.dev_network : key => {
      id                 = value.id, arn = value.arn, name = value.name,
      ip_address_version = value.ip_address_version, addresses = value.addresses
    } }
  }
}

resource "aws_cloudfront_vpc_origin" "application" {
  provider = aws.edge
  vpc_origin_endpoint_config {
    name                   = local.name
    arn                    = data.aws_lb.origin.arn
    http_port              = 80
    https_port             = 8443
    origin_protocol_policy = "https-only"
    origin_ssl_protocols {
      items    = ["TLSv1.2"]
      quantity = 1
    }
  }
  tags = merge({ Project = "CyberCoach", Environment = var.environment, AuthoritySHA256 = var.origin.authority_sha256 }, local.cost_allocation_tags)
  lifecycle {
    precondition {
      condition     = data.aws_caller_identity.regional.account_id == var.account_id && data.aws_caller_identity.edge.account_id == var.account_id && data.aws_region.regional.region == var.region && data.aws_region.edge.region == "us-east-1"
      error_message = "Regional and us-east-1 edge providers must use the exact same approved account."
    }
  }
  depends_on = [data.aws_internet_gateway.origin, data.aws_subnet.origin, data.aws_route_table.origin, data.aws_lb_listener.origin, data.aws_acm_certificate.origin, data.aws_security_group.origin]
}
# AWS creates this reserved service SG only after the first VPC origin. Never
# fabricate it or temporarily allow the global CloudFront prefix list.
data "aws_security_group" "cloudfront" {
  name       = "CloudFront-VPCOrigins-Service-SG"
  vpc_id     = var.origin.vpc_id
  depends_on = [aws_cloudfront_vpc_origin.application]
  lifecycle {
    postcondition {
      condition     = self.vpc_id == var.origin.vpc_id && startswith(self.arn, "arn:aws:ec2:${var.region}:${var.account_id}:security-group/") && self.name == "CloudFront-VPCOrigins-Service-SG"
      error_message = "Use only the observed AWS-managed VPC-origin SG in the exact account/VPC."
    }
  }
}
resource "aws_vpc_security_group_ingress_rule" "cloudfront" {
  tags = local.cost_allocation_tags

  security_group_id            = var.origin.edge_security_group_id
  referenced_security_group_id = data.aws_security_group.cloudfront.id
  from_port                    = 8443
  to_port                      = 8443
  ip_protocol                  = "tcp"
  description                  = "CloudFront VPC origin HTTPS only; external no-sharing authority required"
}
resource "aws_cloudfront_cache_policy" "disabled" {
  provider    = aws.edge
  name        = "${local.name}-disabled"
  min_ttl     = 0
  default_ttl = 0
  max_ttl     = 0
  parameters_in_cache_key_and_forwarded_to_origin {
    enable_accept_encoding_brotli = false
    enable_accept_encoding_gzip   = false
    cookies_config { cookie_behavior = "none" }
    headers_config { header_behavior = "none" }
    query_strings_config { query_string_behavior = "none" }
  }
}
resource "aws_cloudfront_origin_request_policy" "application" {
  provider = aws.edge
  name     = "${local.name}-all-viewer"
  cookies_config { cookie_behavior = "all" }
  query_strings_config { query_string_behavior = "all" }
  headers_config {
    header_behavior = "allViewerAndWhitelistCloudFront"
    headers { items = ["CloudFront-Viewer-Address", "CloudFront-Forwarded-Proto"] }
  }
}
resource "aws_cloudfront_distribution" "application" {
  provider            = aws.edge
  enabled             = var.enabled
  comment             = local.name
  aliases             = [var.origin.hostname]
  is_ipv6_enabled     = true
  http_version        = "http2and3"
  web_acl_id          = aws_wafv2_web_acl.edge.arn
  wait_for_deployment = true
  origin {
    domain_name         = data.aws_lb.origin.dns_name
    origin_id           = local.name
    connection_attempts = 1
    connection_timeout  = 10
    vpc_origin_config {
      vpc_origin_id = aws_cloudfront_vpc_origin.application.id
      # The same-account API omits OwnerAccountId on readback. Ownership is
      # enforced by the provider/VPC/ALB checks, not this optional wire field.
      origin_read_timeout      = 110
      origin_keepalive_timeout = 5
    }
  }
  default_cache_behavior {
    dynamic "lambda_function_association" {
      for_each = var.origin_auth_lambda_arn == null ? [] : [var.origin_auth_lambda_arn]
      content {
        event_type   = "viewer-request"
        lambda_arn   = lambda_function_association.value
        include_body = false
      }
    }
    target_origin_id         = local.name
    viewer_protocol_policy   = "https-only"
    allowed_methods          = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods           = ["GET", "HEAD"]
    min_ttl                  = 0
    default_ttl              = 0
    max_ttl                  = 0
    compress                 = false
    cache_policy_id          = aws_cloudfront_cache_policy.disabled.id
    origin_request_policy_id = aws_cloudfront_origin_request_policy.application.id
  }
  dynamic "custom_error_response" {
    for_each = toset([400, 403, 404, 405, 414, 416, 500, 501, 502, 503, 504])
    content {
      error_code            = custom_error_response.value
      error_caching_min_ttl = 0
    }
  }
  restrictions {
    geo_restriction { restriction_type = "none" }
  }
  viewer_certificate {
    acm_certificate_arn      = data.aws_acm_certificate.edge.arn
    ssl_support_method       = "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"
  }
  tags = merge({ Project = "CyberCoach", Environment = var.environment, AuthoritySHA256 = var.origin.authority_sha256 }, local.cost_allocation_tags)
  # Standard logging v2 selects operational fields in access-logging.tf.
  # No legacy/realtime logs, origin functions, error rewrites, shared asset cache,
  # origin failover, origin custom headers or unsupported completion override.
  depends_on = [aws_vpc_security_group_ingress_rule.cloudfront, data.aws_vpc_security_group_rule.origin]
}
resource "aws_wafv2_web_acl" "edge" {
  provider = aws.edge
  name     = local.name
  scope    = "CLOUDFRONT"
  # DNS can be established before a serving authenticated runtime. This stage
  # blocks every request at the existing WAF; all retained rate rules also block.
  # Application exposure still uses the separate authenticated enable stage.
  default_action {
    dynamic "allow" {
      for_each = var.origin_auth_stage == "dns-only" ? [] : [1]
      content {}
    }
    dynamic "block" {
      for_each = var.origin_auth_stage == "dns-only" ? [1] : []
      content {}
    }
  }
  rule {
    name     = "viewer-ip-rate"
    priority = 0
    action {
      block {}
    }
    statement {
      rate_based_statement {
        aggregate_key_type    = "IP"
        evaluation_window_sec = 300
        limit                 = var.waf_rate_limit
      }
    }
    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "${local.name}-viewer-rate"
      sampled_requests_enabled   = false
    }
  }
  rule {
    name     = "viewer-auth-ip-rate"
    priority = 1
    action {
      block {}
    }
    statement {
      rate_based_statement {
        aggregate_key_type    = "IP"
        evaluation_window_sec = 300
        limit                 = var.waf_auth_rate_limit
        scope_down_statement {
          regex_match_statement {
            regex_string = "^/(auth/saml(/.*)?|api/auth(/.*)?|api/admin(/.*)?)$"
            field_to_match {
              uri_path {}
            }
            text_transformation {
              priority = 0
              type     = "URL_DECODE"
            }
            text_transformation {
              priority = 1
              type     = "NORMALIZE_PATH"
            }
          }
        }
      }
    }
    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "${local.name}-viewer-auth-rate"
      sampled_requests_enabled   = false
    }
  }
  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = local.name
    sampled_requests_enabled   = false
  }
  tags = merge({ Project = "CyberCoach", Environment = var.environment, AuthoritySHA256 = var.origin.authority_sha256 }, local.cost_allocation_tags)
  # Evaluate both existing rate limits before denying viewers outside the
  # reviewed DEV network sets. Matching viewers never bypass a rate rule.
  dynamic "rule" {
    for_each = var.dev_network_policy == null ? [] : [1]
    content {
      name     = "dev-network-restriction"
      priority = 2
      action {
        block {}
      }
      statement {
        not_statement {
          statement {
            or_statement {
              statement {
                ip_set_reference_statement {
                  arn = aws_wafv2_ip_set.dev_network["state"].arn
                }
              }
              statement {
                ip_set_reference_statement {
                  arn = aws_wafv2_ip_set.dev_network["general_ipv4"].arn
                }
              }
              statement {
                ip_set_reference_statement {
                  arn = aws_wafv2_ip_set.dev_network["dor"].arn
                }
              }
              statement {
                ip_set_reference_statement {
                  arn = aws_wafv2_ip_set.dev_network["dor_vpn"].arn
                }
              }
              statement {
                ip_set_reference_statement {
                  arn = aws_wafv2_ip_set.dev_network["general_ipv6"].arn
                }
              }
            }
          }
        }
      }
      visibility_config {
        cloudwatch_metrics_enabled = true
        metric_name                = "${local.name}-dev-network"
        sampled_requests_enabled   = false
      }
    }
  }
}
output "distribution" {
  value = {
    id               = aws_cloudfront_distribution.application.id, arn = aws_cloudfront_distribution.application.arn,
    domain_name      = aws_cloudfront_distribution.application.domain_name,
    hosted_zone_id   = aws_cloudfront_distribution.application.hosted_zone_id,
    hostname         = var.origin.hostname, account_id = var.account_id, environment = var.environment,
    vpc_origin_id    = aws_cloudfront_vpc_origin.application.id, enabled = var.enabled,
    authority_sha256 = var.origin.authority_sha256
  }
}

output "execution" {
  description = "Exact resource-backed IDs for protected post-apply readback and the next signed update authority."
  value = {
    distribution_id               = aws_cloudfront_distribution.application.id
    distribution_arn              = aws_cloudfront_distribution.application.arn
    vpc_origin_id                 = aws_cloudfront_vpc_origin.application.id
    vpc_origin_arn                = aws_cloudfront_vpc_origin.application.arn
    cache_policy_id               = aws_cloudfront_cache_policy.disabled.id
    origin_request_policy_id      = aws_cloudfront_origin_request_policy.application.id
    web_acl_id                    = aws_wafv2_web_acl.edge.id
    web_acl_arn                   = aws_wafv2_web_acl.edge.arn
    ingress_rule_id               = aws_vpc_security_group_ingress_rule.cloudfront.security_group_rule_id
    service_security_group_id     = data.aws_security_group.cloudfront.id
    log_delivery_source_name      = aws_cloudwatch_log_delivery_source.access.name
    log_delivery_destination_name = aws_cloudwatch_log_delivery_destination.access.name
    log_delivery_id               = aws_cloudwatch_log_delivery.access.id
  }
}

sources.infra/aws/modules/records/operator-tests:
# Maintained producer/consumer modules composed with synthetic provider observations.
# Public root passthroughs are validated separately; no backend/child-provider mock claim.
# Timestamps label mock observations only; this module is never a launch input.
variable "environment" { type = string }

locals {
  account = "564503811353"
  fixture = jsondecode(file("${path.module}/../../tests/operator-${var.environment}.json"))
}

module "audit" {
  source                        = "../../../audit-foundation"
  governance_profile            = "operator-managed-v1"
  account_id                    = local.account
  region                        = "us-east-1"
  environment                   = var.environment
  source_purpose                = "records"
  source_buckets                = { records = local.fixture.bucket_name }
  custodian_role_arn            = local.fixture.policy_custodian_role_arn
  plan_role_arn                 = "arn:aws:iam::${local.account}:role/platform-audit/${var.environment}/cybercoach-${var.environment}-foundation-audit-records-plan"
  source_administrator_role_arn = local.fixture.administrator_role_arn
  access_log_receiver = {
    bucket_name               = local.fixture.access_log_destination.bucket_name
    retention_days            = local.fixture.access_log_destination.retention_days
    noncurrent_retention_days = 120
  }
  records_destination = {
    bucket_name               = local.fixture.audit_bucket_name
    retention_days            = 365
    noncurrent_retention_days = 400
    object_lock_days          = local.fixture.retention_days
    access_log_receiver = {
      bucket_name               = "cybercoach-trail-access-${var.environment}"
      retention_days            = 90
      noncurrent_retention_days = 120
    }
    log_group_name            = "/platform/audit/${var.environment}/records"
    cloudwatch_retention_days = local.fixture.operator_audit.retention_days
    alarm_topic_name          = "platform-audit-${var.environment}-records"
    alarm_subscriptions       = { synthetic = { protocol = "email", endpoint = "audit@example.invalid" } }
  }
  review_reference = "SYNTHETIC-NOT-ACCOUNT-APPROVAL"
}

module "records" {
  source                    = "../.."
  governance_profile        = module.audit.operator_records_configuration.governance_profile
  account_id                = local.account
  application_account_id    = local.account
  region                    = "us-east-1"
  environment               = var.environment
  boundary                  = module.audit.operator_records_configuration.boundary
  bucket_name               = local.fixture.bucket_name
  retention_days            = local.fixture.retention_days
  administrator_role_arn    = local.fixture.administrator_role_arn
  policy_custodian_role_arn = local.fixture.policy_custodian_role_arn
  reader_principal_arn      = local.fixture.reader_principal_arn
  permissions_boundary_arn  = local.fixture.permissions_boundary_arn
  retention_guardrail       = module.audit.operator_records_configuration.retention_guardrail
  cloudwatch_audit          = module.audit.operator_records_configuration.cloudwatch_audit
  audit_bucket_name         = module.audit.operator_records_configuration.audit_bucket_name
  audit_kms_key_arn         = module.audit.operator_records_configuration.audit_kms_key_arn
  operator_audit = merge(module.audit.operator_records_configuration.operator_audit, {
    verified_at = timestamp(), change_control = "SYNTHETIC-NOT-ACCOUNT-READBACK"
  })
  access_log_destination = merge(module.audit.access_log_destination_configuration, {
    verified_at = timestamp(), change_control = "SYNTHETIC-NOT-ACCOUNT-READBACK"
  })
}

output "producer" { value = module.audit.operator_records_configuration }
output "consumer" { value = module.records.governance_contract }
output "organization_handoff" { value = module.audit.organization_handoff }

sources.infra/aws/operator-database/hosted/store:
resource "aws_kms_key" "store" {
  for_each                = toset(["journal", "evidence"])
  description             = "CyberCoach ${upper(var.environment)} operator database ${each.key}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = merge(local.tags, { OperatorDatabaseStore = each.key })
  policy = jsonencode({ Version = "2012-10-17", Statement = concat([
    { Sid = "OriginalOperator", Effect = "Allow", Principal = { AWS = local.operator }, Action = "kms:*", Resource = "*", Condition = { StringEquals = { "aws:userid" = local.operator_id } } },
    { Sid = "RecoveryAdministration", Effect = "Allow", Principal = { AWS = "arn:aws:iam::564503811353:root" }, Action = ["kms:DescribeKey", "kms:GetKeyPolicy", "kms:PutKeyPolicy", "kms:EnableKey", "kms:CancelKeyDeletion"], Resource = "*", Condition = { ArnEquals = { "aws:PrincipalArn" = "arn:aws:iam::564503811353:root" } } },
    # Account delegation preserves the identity-policy AND boundary intersection.
    { Sid = "ExactOperationDelegation", Effect = "Allow", Principal = { AWS = "arn:aws:iam::564503811353:root" }, Action = ["kms:Decrypt", "kms:GenerateDataKey"], Resource = "*", Condition = { ArnEquals = { "aws:PrincipalArn" = values(local.role_arns) } } }
    ], [for op, id in local.foundation_ids : {
      Sid       = "Foundation${title(op)}", Effect = "Allow", Principal = { AWS = "arn:aws:iam::564503811353:root" },
      Action    = op == "plan" ? ["kms:DescribeKey", "kms:GetKeyPolicy", "kms:GetKeyRotationStatus", "kms:ListResourceTags"] : ["kms:*"], Resource = "*",
      Condition = { ArnEquals = { "aws:PrincipalArn" = local.foundation_arns[op] }, StringLike = { "aws:userid" = "${id}:*" } }
      }], [for statement in [
      { Sid = "CloudWatchLogs", Effect = "Allow", Principal = { Service = "logs.us-east-1.amazonaws.com" }, Action = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey"], Resource = "*", Condition = { ArnEquals = { "kms:EncryptionContext:aws:logs:arn" = [local.trail_log_arn, "arn:aws:logs:us-east-1:564503811353:log-group:/cybercoach/${var.environment}/operator-database-runner"] } } },
      { Sid = "CloudTrailEncryption", Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" }, Action = ["kms:GenerateDataKey*"], Resource = "*", Condition = { StringEquals = { "aws:SourceArn" = local.trail_arn }, StringLike = { "kms:EncryptionContext:aws:cloudtrail:arn" = local.trail_arn } } },
      { Sid = "CloudTrailDescribeKey", Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" }, Action = ["kms:DescribeKey"], Resource = "*", Condition = { StringEquals = { "aws:SourceArn" = local.trail_arn } } }
    ] : statement if each.key == "evidence"], local.admin_bound ? [
    { Sid = "AdminBindingStoreDelegation", Effect = "Allow", Principal = { AWS = "arn:aws:iam::564503811353:root" }, Action = each.key == "journal" ? ["kms:Decrypt"] : ["kms:GenerateDataKey", "kms:Decrypt"], Resource = "*", Condition = { ArnEquals = { "aws:PrincipalArn" = local.admin_arn }, StringLike = { "aws:userid" = "${var.admin_binding.original_role_id}:database-*" }, StringEquals = { "kms:ViaService" = each.key == "journal" ? "dynamodb.us-east-1.amazonaws.com" : "s3.us-east-1.amazonaws.com", "kms:CallerAccount" = local.account } } }
    ] : [], local.admin_bound && each.key == "evidence" ? [
    { Sid = "AdminBindingKeyMetadata", Effect = "Allow", Principal = { AWS = "arn:aws:iam::564503811353:root" }, Action = ["kms:DescribeKey"], Resource = "*", Condition = { ArnEquals = { "aws:PrincipalArn" = local.admin_arn }, StringLike = { "aws:userid" = "${var.admin_binding.original_role_id}:database-*" } } }
  ] : [], local.startup_key_delegation[each.key]) })
  depends_on = [terraform_data.guard]
  lifecycle { prevent_destroy = true }
}
resource "aws_dynamodb_table" "journal" {
  name                        = local.table_name
  billing_mode                = "PAY_PER_REQUEST"
  hash_key                    = "pk"
  deletion_protection_enabled = true
  attribute {
    name = "pk"
    type = "S"
  }
  point_in_time_recovery { enabled = true }
  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.store["journal"].arn
  }
  ttl {
    attribute_name = "expiresAt"
    enabled        = false
  }
  tags = local.tags
  lifecycle { prevent_destroy = true }
}
resource "aws_dynamodb_resource_policy" "journal" {
  resource_arn = aws_dynamodb_table.journal.arn
  policy = jsonencode({ Version = "2012-10-17", Statement = concat([
    { Sid = "TLSOnly", Effect = "Deny", Principal = "*", Action = "dynamodb:*", Resource = local.table_arn, Condition = { Bool = { "aws:SecureTransport" = "false" } } },
    { Sid = "ExactPrincipals", Effect = "Deny", Principal = "*", Action = "dynamodb:*", Resource = local.table_arn, Condition = { ArnNotEquals = { "aws:PrincipalArn" = concat([local.operator], local.bound ? values(local.role_arns) : [], local.foundation_principals, local.admin_store_principals, local.startup_principals) } } },
    { Sid = "OriginalOperator", Effect = "Deny", Principal = "*", Action = "dynamodb:*", Resource = local.table_arn, Condition = { ArnEquals = { "aws:PrincipalArn" = local.operator }, StringNotEquals = { "aws:userid" = local.operator_id } } },
    { Sid = "PermanentHistory", Effect = "Deny", Principal = "*", Action = ["dynamodb:DeleteTable", "dynamodb:DeleteItem", "dynamodb:BatchWriteItem", "dynamodb:UpdateItem", "dynamodb:PartiQLDelete", "dynamodb:PartiQLInsert", "dynamodb:PartiQLUpdate", "dynamodb:UpdateTimeToLive"], Resource = local.table_arn },
    { Sid = "TransactionOnly", Effect = "Deny", Principal = "*", Action = "dynamodb:PutItem", Resource = local.table_arn, Condition = { StringNotEquals = { "dynamodb:EnclosingOperation" = "TransactWriteItems" } } },
    { Sid = "NoOperatorAdministration", Effect = "Deny", Principal = "*", Action = ["dynamodb:PutResourcePolicy", "dynamodb:DeleteResourcePolicy", "dynamodb:UpdateTable", "dynamodb:UpdateContinuousBackups", "dynamodb:TagResource", "dynamodb:UntagResource"], Resource = local.table_arn, Condition = { ArnNotEquals = { "aws:PrincipalArn" = jsondecode(var.foundation_authority == null ? jsonencode(local.operator) : jsonencode(concat([local.operator], local.foundation_apply_principals))) } } }
    ], [for op, id in var.original_role_ids : { Sid = "OriginalRole${replace(op, "-", "")}", Effect = "Deny", Principal = "*", Action = "dynamodb:*", Resource = local.table_arn, Condition = { ArnEquals = { "aws:PrincipalArn" = local.role_arns[op] }, StringNotLike = { "aws:userid" = "${id}:*" } } }], [for op, id in local.foundation_ids : {
      Sid                                           = "OriginalFoundation${title(op)}", Effect = "Deny", Principal = "*", Action = "dynamodb:*", Resource = local.table_arn,
      Condition                                     = { ArnEquals = { "aws:PrincipalArn" = local.foundation_arns[op] }, StringNotLike = { "aws:userid" = "${id}:*" } }
    }], local.admin_bound ? [
    { Sid = "OriginalAdminBinding", Effect = "Deny", Principal = "*", Action = "dynamodb:*", Resource = local.table_arn, Condition = { ArnEquals = { "aws:PrincipalArn" = local.admin_arn }, StringNotLike = { "aws:userid" = "${var.admin_binding.original_role_id}:database-*" } } }
  ] : [], local.startup_ddb_denies) })
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket" "evidence" {
  bucket              = local.bucket_name
  object_lock_enabled = true
  force_destroy       = false
  tags                = local.tags
  depends_on          = [terraform_data.guard]
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_ownership_controls" "evidence" {
  bucket = aws_s3_bucket.evidence.id
  rule { object_ownership = "BucketOwnerEnforced" }
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_public_access_block" "evidence" {
  bucket                  = aws_s3_bucket.evidence.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_versioning" "evidence" {
  bucket = aws_s3_bucket.evidence.id
  versioning_configuration { status = "Enabled" }
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_server_side_encryption_configuration" "evidence" {
  bucket = aws_s3_bucket.evidence.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.store["evidence"].arn
    }
    bucket_key_enabled = false
  }
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_object_lock_configuration" "evidence" {
  bucket = aws_s3_bucket.evidence.id
  rule {
    default_retention {
      mode = "COMPLIANCE"
      days = 365
    }
  }
  depends_on = [aws_s3_bucket_versioning.evidence]
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_policy" "evidence" {
  bucket = aws_s3_bucket.evidence.id
  policy = jsonencode({ Version = "2012-10-17", Statement = concat([
    { Sid = "TLSOnly", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.bucket_arn, "${local.bucket_arn}/*"], Condition = { Bool = { "aws:SecureTransport" = "false" } } },
    { Sid = "ExactPrincipals", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.bucket_arn, "${local.bucket_arn}/*"], Condition = { ArnNotEquals = { "aws:PrincipalArn" = concat([local.operator], local.bound ? values(local.role_arns) : [], local.foundation_principals, local.admin_store_principals, local.startup_principals) }, Bool = { "aws:PrincipalIsAWSService" = "false" } } },
    { Sid = "NoDeletion", Effect = "Deny", Principal = "*", Action = ["s3:DeleteObject", "s3:DeleteObjectVersion", "s3:BypassGovernanceRetention", "s3:DeleteBucket"], Resource = [local.bucket_arn, "${local.bucket_arn}/*"] },
    { Sid = "AdministrationSeparate", Effect = "Deny", Principal = "*", Action = ["s3:PutBucketPolicy", "s3:DeleteBucketPolicy", "s3:PutBucketVersioning", "s3:PutEncryptionConfiguration", "s3:PutLifecycleConfiguration", "s3:PutBucketObjectLockConfiguration", "s3:PutBucketPublicAccessBlock", "s3:PutObjectLegalHold"], Resource = [local.bucket_arn, "${local.bucket_arn}/*"], Condition = { ArnNotEquals = { "aws:PrincipalArn" = jsondecode(var.foundation_authority == null ? jsonencode(local.operator) : jsonencode(concat([local.operator], local.foundation_apply_principals))) } } },
    { Sid = "ReceiptEncryption", Effect = "Deny", Principal = "*", Action = "s3:PutObject", Resource = local.evidence_prefix, Condition = { StringNotEquals = { "s3:x-amz-server-side-encryption" = "aws:kms" } } },
    { Sid = "ReceiptKey", Effect = "Deny", Principal = "*", Action = "s3:PutObject", Resource = local.evidence_prefix, Condition = { StringNotEquals = { "s3:x-amz-server-side-encryption-aws-kms-key-id" = aws_kms_key.store["evidence"].arn } } },
    { Sid = "ReceiptCompliance", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.evidence_prefix, Condition = { StringNotEquals = { "s3:object-lock-mode" = "COMPLIANCE" } } },
    { Sid = "ReceiptRetention", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.evidence_prefix, Condition = { NumericLessThan = { "s3:object-lock-remaining-retention-days" = "365" } } },
    { Sid = "CloudTrailBucket", Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" }, Action = "s3:GetBucketAcl", Resource = local.bucket_arn, Condition = { StringEquals = { "aws:SourceArn" = local.trail_arn } } },
    { Sid = "CloudTrailDelivery", Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" }, Action = "s3:PutObject", Resource = "${local.bucket_arn}/cloudtrail/AWSLogs/564503811353/*", Condition = { StringEquals = { "aws:SourceArn" = local.trail_arn, "s3:x-amz-acl" = "bucket-owner-full-control" } } }
    ], [for op, id in var.original_role_ids : { Sid = "OriginalRole${replace(op, "-", "")}", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.bucket_arn, "${local.bucket_arn}/*"], Condition = { ArnEquals = { "aws:PrincipalArn" = local.role_arns[op] }, StringNotLike = { "aws:userid" = "${id}:*" } } }], [for op, id in local.foundation_ids : {
      Sid                                           = "OriginalFoundation${title(op)}", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.bucket_arn, "${local.bucket_arn}/*"],
      Condition                                     = { ArnEquals = { "aws:PrincipalArn" = local.foundation_arns[op] }, StringNotLike = { "aws:userid" = "${id}:*" } }
      }], jsondecode(var.admin_binding == null ? "[]" : jsonencode([
        { Sid = "AdminDescriptorPublisher", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.admin_descriptor_prefix, Condition = { ArnNotEquals = { "aws:PrincipalArn" = local.operator } } },
        { Sid = "OriginalAdminDescriptorPublisher", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.admin_descriptor_prefix, Condition = { ArnEquals = { "aws:PrincipalArn" = local.operator }, StringNotEquals = { "aws:userid" = local.operator_id } } },
        { Sid = "AdminDescriptorEncryption", Effect = "Deny", Principal = "*", Action = "s3:PutObject", Resource = local.admin_descriptor_prefix, Condition = { StringNotEquals = { "s3:x-amz-server-side-encryption" = "aws:kms" } } },
        { Sid = "AdminDescriptorKey", Effect = "Deny", Principal = "*", Action = "s3:PutObject", Resource = local.admin_descriptor_prefix, Condition = { StringNotEquals = { "s3:x-amz-server-side-encryption-aws-kms-key-id" = aws_kms_key.store["evidence"].arn } } },
        { Sid = "AdminDescriptorCompliance", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.admin_descriptor_prefix, Condition = { StringNotEquals = { "s3:object-lock-mode" = "COMPLIANCE" } } },
        { Sid = "AdminDescriptorRetention", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.admin_descriptor_prefix, Condition = { NumericLessThan = { "s3:object-lock-remaining-retention-days" = "365" } } }
    ])), local.admin_bound ? [
    { Sid = "OriginalAdminBinding", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.bucket_arn, "${local.bucket_arn}/*"], Condition = { ArnEquals = { "aws:PrincipalArn" = local.admin_arn }, StringNotLike = { "aws:userid" = "${var.admin_binding.original_role_id}:database-*" } } }
  ] : [], local.startup_s3_denies) })
  depends_on = [aws_s3_bucket_public_access_block.evidence, aws_s3_bucket_object_lock_configuration.evidence, aws_s3_bucket_server_side_encryption_configuration.evidence]
  lifecycle { prevent_destroy = true }
}
resource "aws_cloudwatch_log_group" "trail" {
  name                        = "/cybercoach/${var.environment}/operator-cloudtrail"
  kms_key_id                  = aws_kms_key.store["evidence"].arn
  retention_in_days           = 365
  deletion_protection_enabled = true
  tags                        = local.tags
  lifecycle { prevent_destroy = true }
}
resource "aws_iam_role" "trail" {
  name               = "cybercoach-${var.environment}-database-cloudtrail"
  path               = "/platform/${var.environment}/"
  assume_role_policy = jsonencode({ Version = "2012-10-17", Statement = [{ Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" }, Action = "sts:AssumeRole", Condition = { StringEquals = { "aws:SourceArn" = local.trail_arn, "aws:SourceAccount" = local.account } } }] })
  tags               = local.tags
  depends_on         = [terraform_data.guard]
  lifecycle { prevent_destroy = true }
}
resource "aws_iam_role_policy" "trail" {
  role   = aws_iam_role.trail.id
  name   = "ExactCloudTrailDelivery"
  policy = jsonencode({ Version = "2012-10-17", Statement = [{ Effect = "Allow", Action = ["logs:CreateLogStream", "logs:PutLogEvents"], Resource = "${local.trail_log_arn}:log-stream:564503811353_CloudTrail_us-east-1*" }] })
  lifecycle { prevent_destroy = true }
}
resource "aws_cloudtrail" "database" {
  count                         = local.retain_native_trail ? 1 : 0
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.evidence.id
  s3_key_prefix                 = "cloudtrail"
  kms_key_id                    = aws_kms_key.store["evidence"].arn
  include_global_service_events = false
  is_multi_region_trail         = false
  enable_log_file_validation    = true
  enable_logging                = true
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.trail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.trail.arn
  event_selector {
    read_write_type           = "WriteOnly"
    include_management_events = true
  }
  tags       = local.tags
  depends_on = [aws_s3_bucket_policy.evidence, aws_iam_role_policy.trail]
  # Only this redundant configuration may be retired by explicit selection.
  # All history buckets, keys, groups and IAM addresses retain prevent_destroy.
}

# Reuse the existing SSE-S3 receiver. Infra must integrate the exact additional
# source/prefix statement before applying this root; no shared policy is edited.
data "aws_s3_bucket" "access_receiver" {
  bucket = "cybercoach-564503811353-operator-v1-${var.environment}-access-logs"
}
resource "aws_s3_bucket_logging" "evidence" {
  bucket                = aws_s3_bucket.evidence.id
  expected_bucket_owner = local.account
  target_bucket         = data.aws_s3_bucket.access_receiver.id
  target_prefix         = "operator-database/${var.environment}/"
  target_object_key_format {
    simple_prefix {}
  }
  lifecycle {
    prevent_destroy = true
    precondition {
      condition     = data.aws_s3_bucket.access_receiver.bucket_region == "us-east-1" && data.aws_s3_bucket.access_receiver.arn == "arn:aws:s3:::cybercoach-564503811353-operator-v1-${var.environment}-access-logs"
      error_message = "Existing selected-environment receiver must resolve exactly; separately verify receiver delivery permission."
    }
  }
}

sources.infra/aws/operator-database/stores.tf:
resource "aws_kms_key" "store" {
  for_each                = toset(["journal", "evidence"])
  description             = "CyberCoach DEV operator database ${each.key}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.tags
  policy = jsonencode({ Version = "2012-10-17", Statement = concat([
    { Sid = "OriginalOperator", Effect = "Allow", Principal = { AWS = local.operator }, Action = "kms:*", Resource = "*", Condition = { StringEquals = { "aws:userid" = local.operator_id } } },
    { Sid = "RecoveryAdministration", Effect = "Allow", Principal = { AWS = "arn:aws:iam::564503811353:root" }, Action = ["kms:DescribeKey", "kms:GetKeyPolicy", "kms:PutKeyPolicy", "kms:EnableKey", "kms:CancelKeyDeletion"], Resource = "*", Condition = { ArnEquals = { "aws:PrincipalArn" = "arn:aws:iam::564503811353:root" } } },
    # Account delegation preserves the identity-policy AND boundary intersection.
    { Sid = "ExactOperationDelegation", Effect = "Allow", Principal = { AWS = "arn:aws:iam::564503811353:root" }, Action = ["kms:Decrypt", "kms:GenerateDataKey"], Resource = "*", Condition = { ArnEquals = { "aws:PrincipalArn" = values(local.role_arns) } } }
    ], [for statement in [
      { Sid = "CloudWatchLogs", Effect = "Allow", Principal = { Service = "logs.us-east-1.amazonaws.com" }, Action = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey"], Resource = "*", Condition = { ArnEquals = { "kms:EncryptionContext:aws:logs:arn" = [local.trail_log_arn, "arn:aws:logs:us-east-1:564503811353:log-group:/cybercoach/dev/operator-database-runner"] } } },
      { Sid = "CloudTrailEncryption", Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" }, Action = ["kms:GenerateDataKey*"], Resource = "*", Condition = { StringEquals = { "aws:SourceArn" = local.trail_arn }, StringLike = { "kms:EncryptionContext:aws:cloudtrail:arn" = local.trail_arn } } },
      { Sid = "CloudTrailDescribeKey", Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" }, Action = ["kms:DescribeKey"], Resource = "*", Condition = { StringEquals = { "aws:SourceArn" = local.trail_arn } } }
    ] : statement if each.key == "evidence"], local.native_bound ? [
    { Sid = "NativeOperationDelegation", Effect = "Allow", Principal = { AWS = "arn:aws:iam::564503811353:root" }, Action = each.key == "journal" ? ["kms:Decrypt"] : ["kms:GenerateDataKey", "kms:Decrypt"], Resource = "*", Condition = merge(
      { ArnEquals = { "aws:PrincipalArn" = local.native_arns.operation }, StringLike = merge({ "aws:userid" = "${lookup(var.original_native_role_ids, "operation", "UNBOUND")}:native-db-*" }, each.key == "evidence" ? { "kms:EncryptionContext:aws:s3:arn" = local.native_terminal_prefix } : {}) },
      { StringEquals = merge({ "kms:ViaService" = each.key == "journal" ? "dynamodb.us-east-1.amazonaws.com" : "s3.us-east-1.amazonaws.com", "kms:CallerAccount" = local.account, "aws:SourceIdentity" = local.operator_id }, each.key == "journal" ? { "kms:EncryptionContext:aws:dynamodb:tableName" = local.table_name } : {}) }
    ) }
    ] : [], local.native_bound && each.key == "evidence" ? [
    { Sid = "NativeRequestDecryption", Effect = "Allow", Principal = { AWS = "arn:aws:iam::564503811353:root" }, Action = ["kms:Decrypt"], Resource = "*", Condition = { ArnEquals = { "aws:PrincipalArn" = local.native_arns.service }, StringLike = { "aws:userid" = "${lookup(var.original_native_role_ids, "service", "UNBOUND")}:AWSCodeBuild-*", "kms:EncryptionContext:aws:s3:arn" = local.native_request_prefix }, StringEquals = { "kms:ViaService" = "s3.us-east-1.amazonaws.com", "kms:CallerAccount" = local.account } } }
    ] : [], local.admin_bound ? [
    { Sid = "AdminBindingStoreDelegation", Effect = "Allow", Principal = { AWS = "arn:aws:iam::564503811353:root" }, Action = each.key == "journal" ? ["kms:Decrypt"] : ["kms:GenerateDataKey", "kms:Decrypt"], Resource = "*", Condition = { ArnEquals = { "aws:PrincipalArn" = local.admin_arn }, StringLike = { "aws:userid" = "${var.admin_binding.original_role_id}:database-*" }, StringEquals = { "kms:ViaService" = each.key == "journal" ? "dynamodb.us-east-1.amazonaws.com" : "s3.us-east-1.amazonaws.com", "kms:CallerAccount" = local.account } } }
    ] : [], local.admin_bound && each.key == "evidence" ? [
    { Sid = "AdminBindingKeyMetadata", Effect = "Allow", Principal = { AWS = "arn:aws:iam::564503811353:root" }, Action = ["kms:DescribeKey"], Resource = "*", Condition = { ArnEquals = { "aws:PrincipalArn" = local.admin_arn }, StringLike = { "aws:userid" = "${var.admin_binding.original_role_id}:database-*" } } }
  ] : [], local.ai_resume_key_statements[each.key]) })
  depends_on = [terraform_data.guard]
  lifecycle { prevent_destroy = true }
}
resource "aws_dynamodb_table" "journal" {
  name                        = local.table_name
  billing_mode                = "PAY_PER_REQUEST"
  hash_key                    = "pk"
  deletion_protection_enabled = true
  attribute {
    name = "pk"
    type = "S"
  }
  point_in_time_recovery { enabled = true }
  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.store["journal"].arn
  }
  ttl {
    attribute_name = "expiresAt"
    enabled        = false
  }
  tags = local.tags
  lifecycle { prevent_destroy = true }
}
resource "aws_dynamodb_resource_policy" "journal" {
  resource_arn = aws_dynamodb_table.journal.arn
  policy = jsonencode({ Version = "2012-10-17", Statement = concat([
    { Sid = "TLSOnly", Effect = "Deny", Principal = "*", Action = "dynamodb:*", Resource = local.table_arn, Condition = { Bool = { "aws:SecureTransport" = "false" } } },
    { Sid = "ExactPrincipals", Effect = "Deny", Principal = "*", Action = "dynamodb:*", Resource = local.table_arn, Condition = { ArnNotEquals = { "aws:PrincipalArn" = concat([local.operator], local.bound ? values(local.role_arns) : [], local.native_bound ? [local.native_arns.operation] : [], local.admin_store_principals, local.ai_resume_principals) } } },
    { Sid = "OriginalOperator", Effect = "Deny", Principal = "*", Action = "dynamodb:*", Resource = local.table_arn, Condition = { ArnEquals = { "aws:PrincipalArn" = local.operator }, StringNotEquals = { "aws:userid" = local.operator_id } } },
    { Sid = "PermanentHistory", Effect = "Deny", Principal = "*", Action = ["dynamodb:DeleteTable", "dynamodb:DeleteItem", "dynamodb:BatchWriteItem", "dynamodb:UpdateItem", "dynamodb:PartiQLDelete", "dynamodb:PartiQLInsert", "dynamodb:PartiQLUpdate", "dynamodb:UpdateTimeToLive"], Resource = local.table_arn },
    { Sid = "TransactionOnly", Effect = "Deny", Principal = "*", Action = "dynamodb:PutItem", Resource = local.table_arn, Condition = { StringNotEquals = { "dynamodb:EnclosingOperation" = "TransactWriteItems" } } },
    { Sid = "NoOperatorAdministration", Effect = "Deny", Principal = "*", Action = ["dynamodb:PutResourcePolicy", "dynamodb:DeleteResourcePolicy", "dynamodb:UpdateTable", "dynamodb:UpdateContinuousBackups", "dynamodb:TagResource", "dynamodb:UntagResource"], Resource = local.table_arn, Condition = { ArnNotEquals = { "aws:PrincipalArn" = local.operator } } }
    ], [for op, id in var.original_role_ids : { Sid = "OriginalRole${replace(op, "-", "")}", Effect = "Deny", Principal = "*", Action = "dynamodb:*", Resource = local.table_arn, Condition = { ArnEquals = { "aws:PrincipalArn" = local.role_arns[op] }, StringNotLike = { "aws:userid" = "${id}:*" } } }], local.native_bound ? [
    { Sid = "OriginalNativeOperation", Effect = "Deny", Principal = "*", Action = "dynamodb:*", Resource = local.table_arn, Condition = { ArnEquals = { "aws:PrincipalArn" = local.native_arns.operation }, StringNotLike = { "aws:userid" = "${lookup(var.original_native_role_ids, "operation", "UNBOUND")}:native-db-*" } } }
    ] : [], local.admin_bound ? [
    { Sid = "OriginalAdminBinding", Effect = "Deny", Principal = "*", Action = "dynamodb:*", Resource = local.table_arn, Condition = { ArnEquals = { "aws:PrincipalArn" = local.admin_arn }, StringNotLike = { "aws:userid" = "${var.admin_binding.original_role_id}:database-*" } } }
  ] : [], local.ai_resume_journal_statements) })
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket" "evidence" {
  bucket              = local.bucket_name
  object_lock_enabled = true
  force_destroy       = false
  tags                = local.tags
  depends_on          = [terraform_data.guard]
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_ownership_controls" "evidence" {
  bucket = aws_s3_bucket.evidence.id
  rule { object_ownership = "BucketOwnerEnforced" }
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_public_access_block" "evidence" {
  bucket                  = aws_s3_bucket.evidence.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_versioning" "evidence" {
  bucket = aws_s3_bucket.evidence.id
  versioning_configuration { status = "Enabled" }
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_server_side_encryption_configuration" "evidence" {
  bucket = aws_s3_bucket.evidence.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.store["evidence"].arn
    }
    bucket_key_enabled = false
  }
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_object_lock_configuration" "evidence" {
  bucket = aws_s3_bucket.evidence.id
  rule {
    default_retention {
      mode = "COMPLIANCE"
      days = 365
    }
  }
  depends_on = [aws_s3_bucket_versioning.evidence]
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_policy" "evidence" {
  bucket = aws_s3_bucket.evidence.id
  policy = jsonencode({ Version = "2012-10-17", Statement = concat([
    { Sid = "TLSOnly", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.bucket_arn, "${local.bucket_arn}/*"], Condition = { Bool = { "aws:SecureTransport" = "false" } } },
    { Sid = "ExactPrincipals", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.bucket_arn, "${local.bucket_arn}/*"], Condition = { ArnNotEquals = { "aws:PrincipalArn" = concat([local.operator], local.bound ? values(local.role_arns) : [], local.native_bound ? values(local.native_arns) : [], local.admin_store_principals, local.ai_resume_principals) }, Bool = { "aws:PrincipalIsAWSService" = "false" } } },
    { Sid = "NoDeletion", Effect = "Deny", Principal = "*", Action = ["s3:DeleteObject", "s3:DeleteObjectVersion", "s3:BypassGovernanceRetention", "s3:DeleteBucket"], Resource = [local.bucket_arn, "${local.bucket_arn}/*"] },
    { Sid = "AdministrationSeparate", Effect = "Deny", Principal = "*", Action = ["s3:PutBucketPolicy", "s3:DeleteBucketPolicy", "s3:PutBucketVersioning", "s3:PutEncryptionConfiguration", "s3:PutLifecycleConfiguration", "s3:PutBucketObjectLockConfiguration", "s3:PutBucketPublicAccessBlock", "s3:PutObjectLegalHold"], Resource = [local.bucket_arn, "${local.bucket_arn}/*"], Condition = { ArnNotEquals = { "aws:PrincipalArn" = local.operator } } },
    { Sid = "ReceiptEncryption", Effect = "Deny", Principal = "*", Action = "s3:PutObject", Resource = local.evidence_prefix, Condition = { StringNotEquals = { "s3:x-amz-server-side-encryption" = "aws:kms" } } },
    { Sid = "ReceiptKey", Effect = "Deny", Principal = "*", Action = "s3:PutObject", Resource = local.evidence_prefix, Condition = { StringNotEquals = { "s3:x-amz-server-side-encryption-aws-kms-key-id" = aws_kms_key.store["evidence"].arn } } },
    { Sid = "ReceiptCompliance", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.evidence_prefix, Condition = { StringNotEquals = { "s3:object-lock-mode" = "COMPLIANCE" } } },
    { Sid = "ReceiptRetention", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.evidence_prefix, Condition = { NumericLessThan = { "s3:object-lock-remaining-retention-days" = "365" } } },
    { Sid = "CloudTrailBucket", Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" }, Action = "s3:GetBucketAcl", Resource = local.bucket_arn, Condition = { StringEquals = { "aws:SourceArn" = local.trail_arn } } },
    { Sid = "CloudTrailDelivery", Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" }, Action = "s3:PutObject", Resource = "${local.bucket_arn}/cloudtrail/AWSLogs/564503811353/*", Condition = { StringEquals = { "aws:SourceArn" = local.trail_arn, "s3:x-amz-acl" = "bucket-owner-full-control" } } }
    ], [for op, id in var.original_role_ids : { Sid = "OriginalRole${replace(op, "-", "")}", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.bucket_arn, "${local.bucket_arn}/*"], Condition = { ArnEquals = { "aws:PrincipalArn" = local.role_arns[op] }, StringNotLike = { "aws:userid" = "${id}:*" } } }], [for kind, id in var.original_native_role_ids :
    { Sid = "OriginalNative${kind}", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.bucket_arn, "${local.bucket_arn}/*"], Condition = { ArnEquals = { "aws:PrincipalArn" = local.native_arns[kind] }, StringNotLike = { "aws:userid" = "${id}:${kind == "service" ? "AWSCodeBuild-*" : "native-db-*"}" } } }
    ], var.native == null ? [] : [
    { Sid = "NativeRequestPublisher", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.native_request_prefix, Condition = { ArnNotEquals = { "aws:PrincipalArn" = local.operator } } },
    { Sid = "OriginalNativeRequestPublisher", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.native_request_prefix, Condition = { ArnEquals = { "aws:PrincipalArn" = local.operator }, StringNotEquals = { "aws:userid" = local.operator_id } } }
    ], jsondecode(var.admin_binding == null ? "[]" : jsonencode([
      { Sid = "AdminDescriptorPublisher", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.admin_descriptor_prefix, Condition = { ArnNotEquals = { "aws:PrincipalArn" = local.operator } } },
      { Sid = "OriginalAdminDescriptorPublisher", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.admin_descriptor_prefix, Condition = { ArnEquals = { "aws:PrincipalArn" = local.operator }, StringNotEquals = { "aws:userid" = local.operator_id } } },
      { Sid = "AdminDescriptorEncryption", Effect = "Deny", Principal = "*", Action = "s3:PutObject", Resource = local.admin_descriptor_prefix, Condition = { StringNotEquals = { "s3:x-amz-server-side-encryption" = "aws:kms" } } },
      { Sid = "AdminDescriptorKey", Effect = "Deny", Principal = "*", Action = "s3:PutObject", Resource = local.admin_descriptor_prefix, Condition = { StringNotEquals = { "s3:x-amz-server-side-encryption-aws-kms-key-id" = aws_kms_key.store["evidence"].arn } } },
      { Sid = "AdminDescriptorCompliance", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.admin_descriptor_prefix, Condition = { StringNotEquals = { "s3:object-lock-mode" = "COMPLIANCE" } } },
      { Sid = "AdminDescriptorRetention", Effect = "Deny", Principal = "*", Action = ["s3:PutObject", "s3:PutObjectRetention"], Resource = local.admin_descriptor_prefix, Condition = { NumericLessThan = { "s3:object-lock-remaining-retention-days" = "365" } } }
    ])), local.admin_bound ? [
    { Sid = "OriginalAdminBinding", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.bucket_arn, "${local.bucket_arn}/*"], Condition = { ArnEquals = { "aws:PrincipalArn" = local.admin_arn }, StringNotLike = { "aws:userid" = "${var.admin_binding.original_role_id}:database-*" } } }
  ] : [], local.ai_resume_evidence_statements) })
  depends_on = [aws_s3_bucket_public_access_block.evidence, aws_s3_bucket_object_lock_configuration.evidence, aws_s3_bucket_server_side_encryption_configuration.evidence]
  lifecycle { prevent_destroy = true }
}
resource "aws_cloudwatch_log_group" "trail" {
  name                        = "/cybercoach/dev/operator-cloudtrail"
  kms_key_id                  = aws_kms_key.store["evidence"].arn
  retention_in_days           = 365
  deletion_protection_enabled = true
  tags                        = local.tags
  lifecycle { prevent_destroy = true }
}
resource "aws_iam_role" "trail" {
  name               = "cybercoach-dev-database-cloudtrail"
  path               = "/platform/dev/"
  assume_role_policy = jsonencode({ Version = "2012-10-17", Statement = [{ Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" }, Action = "sts:AssumeRole", Condition = { StringEquals = { "aws:SourceArn" = local.trail_arn, "aws:SourceAccount" = local.account } } }] })
  tags               = local.tags
  depends_on         = [terraform_data.guard]
  lifecycle { prevent_destroy = true }
}
resource "aws_iam_role_policy" "trail" {
  role   = aws_iam_role.trail.id
  name   = "ExactCloudTrailDelivery"
  policy = jsonencode({ Version = "2012-10-17", Statement = [{ Effect = "Allow", Action = ["logs:CreateLogStream", "logs:PutLogEvents"], Resource = "${local.trail_log_arn}:log-stream:564503811353_CloudTrail_us-east-1*" }] })
  lifecycle { prevent_destroy = true }
}
resource "aws_cloudtrail" "database" {
  count                         = local.retain_native_trail ? 1 : 0
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.evidence.id
  s3_key_prefix                 = "cloudtrail"
  kms_key_id                    = aws_kms_key.store["evidence"].arn
  include_global_service_events = false
  is_multi_region_trail         = false
  enable_log_file_validation    = true
  enable_logging                = true
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.trail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.trail.arn
  event_selector {
    read_write_type           = "WriteOnly"
    include_management_events = true
    dynamic "data_resource" {
      for_each = var.employee_custody_audit == null ? [] : [
        { type = "AWS::DynamoDB::Table", values = [var.employee_custody_audit.table_arn] },
        { type = "AWS::S3::Object", values = [var.employee_custody_audit.bucket_arn] }
      ]
      content {
        type   = data_resource.value.type
        values = data_resource.value.values
      }
    }
  }
  tags       = local.tags
  depends_on = [aws_s3_bucket_policy.evidence, aws_iam_role_policy.trail]
  # Only this redundant configuration may be retired by explicit selection.
  # All history buckets, keys, groups and IAM addresses retain prevent_destroy.
}

# Reuse the existing SSE-S3 receiver. Infra must integrate the exact additional
# source/prefix statement before applying this root; no shared policy is edited.
data "aws_s3_bucket" "access_receiver" {
  bucket = "cybercoach-564503811353-operator-v1-dev-access-logs"
}
resource "aws_s3_bucket_logging" "evidence" {
  bucket                = aws_s3_bucket.evidence.id
  expected_bucket_owner = local.account
  target_bucket         = data.aws_s3_bucket.access_receiver.id
  target_prefix         = "operator-database/dev/"
  target_object_key_format {
    simple_prefix {}
  }
  lifecycle {
    prevent_destroy = true
    precondition {
      condition     = data.aws_s3_bucket.access_receiver.bucket_region == "us-east-1" && data.aws_s3_bucket.access_receiver.arn == "arn:aws:s3:::cybercoach-564503811353-operator-v1-dev-access-logs"
      error_message = "Existing DEV receiver must resolve exactly; separately verify receiver delivery permission."
    }
  }
}

sources.infra/aws/operator-foundations/access-lo:
variable "environment_custody_logging" {
  description = "Optional exact same-environment common-store log delivery plus original provisioner GetBucketPolicy only. Receiver ownership/retention and existing sources are unchanged."
  type        = object({ source_bucket = string, provisioner = object({ arn = string, id = string, boundary_arn = string }) })
  default     = null
  validation {
    condition = var.environment_custody_logging == null ? true : (
      contains(["dev", "production"], var.environment) &&
      (var.stage == "bind" || (var.environment == "production" && var.stage == "create" && var.production_custody_storage && length(var.bindings) == 0)) &&
      var.environment_custody_logging.source_bucket == "cybercoach-564503811353-environment-custody-${var.environment}" &&
      var.environment_custody_logging.provisioner.arn == "arn:aws:iam::564503811353:role/platform/${var.environment}/cybercoach-${var.environment}-custody-provisioner" &&
      (var.environment == "dev" ? var.environment_custody_logging.provisioner.id == "AROAYG3YMSUM3JY2375QP" : (can(regex("^AROA[A-Z0-9]{17}$", var.environment_custody_logging.provisioner.id)) && var.environment_custody_logging.provisioner.id != "AROAYG3YMSUM3JY2375QP")) &&
      var.environment_custody_logging.provisioner.boundary_arn == "arn:aws:iam::564503811353:policy/platform/${var.environment}/cybercoach-${var.environment}-custody-provisioner-boundary"
    )
    error_message = "Only the selected same-environment store and original exact provisioner identity may use this receiver."
  }
}
# S3 server access log delivery requires SSE-S3 and a destination without Object
# Lock. This private receiver deliberately does not log to itself (or any source).
# It is operator managed, not an independent or immutable audit archive.
locals {
  access_log_bucket = "${local.prefix}-access-logs"
  access_log_arn    = "arn:aws:s3:::${local.access_log_bucket}"
  access_logging = {
    bucket              = local.access_log_bucket
    region              = local.region
    account             = local.account
    encryption          = "AES256"
    ownership           = "BucketOwnerEnforced"
    versioning          = "Enabled"
    object_lock_enabled = false
    recursive_logging   = false
    retention_days      = 365
    noncurrent_days     = 30
    sources = { for kind, bucket in local.buckets : kind => {
      bucket = bucket, target_bucket = local.access_log_bucket, target_prefix = "${kind}/"
    } }
  }
  access_log_policy = jsonencode({ Version = "2012-10-17", Statement = concat([
    { Sid = "TLSOnly", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.access_log_arn, "${local.access_log_arn}/*"], Condition = { Bool = { "aws:SecureTransport" = "false", "aws:PrincipalIsAWSService" = "false" } } },
    { Sid = "OnlyOperatorAndLogDelivery", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.access_log_arn, "${local.access_log_arn}/*"], Condition = { ArnNotEquals = { "aws:PrincipalArn" = concat([local.operator, "arn:aws:iam::${local.account}:root"], var.environment_custody_logging == null ? [] : [var.environment_custody_logging.provisioner.arn]) }, StringNotEquals = { "aws:PrincipalServiceName" = "logging.s3.amazonaws.com" } } },
    { Sid = "ScopedOperatorRepair", Effect = "Allow", Principal = { AWS = local.operator }, Action = "s3:*", Resource = [local.access_log_arn, "${local.access_log_arn}/*"] },
    { Sid = "NoExplicitWrongEncryption", Effect = "Deny", Principal = "*", Action = "s3:PutObject", Resource = "${local.access_log_arn}/*", Condition = { StringNotEquals = { "s3:x-amz-server-side-encryption" = "AES256" }, Null = { "s3:x-amz-server-side-encryption" = "false" } } }
    ], [for kind, bucket in local.buckets : {
      Sid       = "Delivery${title(kind)}", Effect = "Allow", Principal = { Service = "logging.s3.amazonaws.com" }, Action = "s3:PutObject", Resource = "${local.access_log_arn}/${kind}/*",
      Condition = { StringEquals = { "aws:SourceAccount" = local.account }, ArnEquals = { "aws:SourceArn" = "arn:aws:s3:::${bucket}" } }
      }], [{
      Sid       = "OperatorRetainedAssetLogs", Effect = "Allow", Principal = { Service = "logging.s3.amazonaws.com" }, Action = "s3:PutObject",
      Resource  = "${local.access_log_arn}/retained-assets/${var.environment}/cybercoach-${var.environment}-assets-564503811353-operator-v1/*",
      Condition = { StringEquals = { "aws:SourceAccount" = local.account }, ArnEquals = { "aws:SourceArn" = "arn:aws:s3:::cybercoach-${var.environment}-assets-564503811353-operator-v1" } }
      }, {
      Sid       = "OperatorDatabaseReceiptLogs", Effect = "Allow", Principal = { Service = "logging.s3.amazonaws.com" }, Action = "s3:PutObject",
      Resource  = "${local.access_log_arn}/operator-database/${var.environment}/*",
      Condition = { StringEquals = { "aws:SourceAccount" = local.account }, ArnEquals = { "aws:SourceArn" = "arn:aws:s3:::cybercoach-564503811353-${var.environment}-operator-database-evidence" } }
      }], jsondecode(var.environment_custody_logging == null ? "[]" : jsonencode([
        { Sid = "EnvironmentCustodyProvisionerMetadataOnly", Effect = "Deny", Principal = "*", NotAction = "s3:GetBucketPolicy", Resource = [local.access_log_arn, "${local.access_log_arn}/*"], Condition = { ArnEquals = { "aws:PrincipalArn" = var.environment_custody_logging.provisioner.arn } } },
        { Sid = "EnvironmentCustodyProvisionerOriginalId", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [local.access_log_arn, "${local.access_log_arn}/*"], Condition = { ArnEquals = { "aws:PrincipalArn" = var.environment_custody_logging.provisioner.arn }, StringNotLike = { "aws:userid" = "${var.environment_custody_logging.provisioner.id}:*" } } },
        { Sid = "EnvironmentCustodyProvisionerReadPolicy", Effect = "Allow", Principal = { AWS = var.environment_custody_logging.provisioner.arn }, Action = "s3:GetBucketPolicy", Resource = local.access_log_arn, Condition = { StringLike = { "aws:userid" = "${var.environment_custody_logging.provisioner.id}:*" } } },
        { Sid = "EnvironmentCustodyLogs", Effect = "Allow", Principal = { Service = "logging.s3.amazonaws.com" }, Action = "s3:PutObject", Resource = "${local.access_log_arn}/environment-custody/${var.environment}/${var.environment_custody_logging.source_bucket}/*", Condition = { StringEquals = { "aws:SourceAccount" = local.account }, ArnEquals = { "aws:SourceArn" = "arn:aws:s3:::${var.environment_custody_logging.source_bucket}" } } }
  ]))) })
}
resource "aws_s3_bucket" "access_logs" {
  bucket              = local.access_log_bucket
  object_lock_enabled = false
  force_destroy       = false
  tags                = local.tags
  lifecycle { prevent_destroy = true }
  depends_on = [terraform_data.guard]
}
resource "aws_s3_bucket_ownership_controls" "access_logs" {
  bucket = aws_s3_bucket.access_logs.bucket
  rule { object_ownership = "BucketOwnerEnforced" }
  lifecycle { prevent_destroy = true }
  depends_on = [aws_s3_bucket.access_logs]
}
resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket                  = aws_s3_bucket.access_logs.bucket
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
  lifecycle { prevent_destroy = true }
  depends_on = [aws_s3_bucket.access_logs]
}
resource "aws_s3_bucket_versioning" "access_logs" {
  bucket = aws_s3_bucket.access_logs.bucket
  versioning_configuration { status = "Enabled" }
  lifecycle { prevent_destroy = true }
  depends_on = [aws_s3_bucket.access_logs]
}
resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.bucket
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "AES256"
      kms_master_key_id = ""
    }
    bucket_key_enabled = false
  }
  lifecycle { prevent_destroy = true }
  depends_on = [aws_s3_bucket.access_logs]
}
resource "aws_s3_bucket_lifecycle_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.bucket
  rule {
    id     = "bounded-access-log-retention"
    status = "Enabled"
    filter { prefix = "" }
    expiration { days = 365 }
    noncurrent_version_expiration { noncurrent_days = 30 }
    abort_incomplete_multipart_upload { days_after_initiation = 7 }
  }
  rule {
    id     = "expired-delete-markers"
    status = "Enabled"
    filter { prefix = "" }
    expiration { expired_object_delete_marker = true }
  }
  lifecycle { prevent_destroy = true }
  depends_on = [aws_s3_bucket_versioning.access_logs]
}
resource "aws_s3_bucket_policy" "access_logs" {
  bucket = aws_s3_bucket.access_logs.bucket
  policy = local.access_log_policy
  lifecycle { prevent_destroy = true }
  depends_on = [aws_s3_bucket_public_access_block.access_logs, data.aws_iam_role.production_custody_log_provisioner]
}
resource "aws_s3_bucket_logging" "store" {
  for_each              = local.buckets
  bucket                = aws_s3_bucket.store[each.key].bucket
  expected_bucket_owner = local.account
  target_bucket         = aws_s3_bucket.access_logs.bucket
  target_prefix         = "${each.key}/"
  target_object_key_format {
    simple_prefix {}
  }
  lifecycle { prevent_destroy = true }
  depends_on = [aws_s3_bucket.store, aws_s3_bucket_policy.access_logs, aws_s3_bucket_ownership_controls.access_logs, aws_s3_bucket_server_side_encryption_configuration.access_logs, aws_s3_bucket_lifecycle_configuration.access_logs]
}
output "access_logging" {
  description = "Configuration only: best-effort S3 delivery remains unassessed until actual log object readback."
  value       = merge(local.access_logging, { policy = local.access_log_policy })
}

# PROD identities are created closed first; bind the actual post-install RoleId
# before changing the existing receiver. DEV retains its original fixed identity.
data "aws_iam_role" "production_custody_log_provisioner" {
  count = var.environment == "production" && var.environment_custody_logging != null ? 1 : 0
  name  = "cybercoach-production-custody-provisioner"
  lifecycle {
    postcondition {
      condition     = self.arn == var.environment_custody_logging.provisioner.arn && self.unique_id == var.environment_custody_logging.provisioner.id && self.permissions_boundary == var.environment_custody_logging.provisioner.boundary_arn
      error_message = "The installed PROD provisioner RoleId, ARN and boundary must match exactly."
    }
  }
}

sources.infra/aws/origin-authentication/main.tf:
terraform {
  required_version = "= 1.11.2"
  required_providers { aws = { source = "hashicorp/aws", version = "= 6.50.0" } }
  backend "s3" {}
}
provider "aws" {
  region              = "us-east-1"
  allowed_account_ids = [var.account_id]
  default_tags { tags = { Project = "CyberCoach", Environment = var.environment, ManagedBy = "OpenTofu", BillingOwner = "Mac Clark" } }
}
# The final policy permits only the independent custodian to manage it.
# Keep the deployment caller for the backend, Lambda and its execution identity.
provider "aws" {
  alias               = "origin_custodian"
  region              = "us-east-1"
  allowed_account_ids = [var.account_id]
  assume_role {
    role_arn     = var.custodian_role_arn
    session_name = "cybercoach-origin-secret-policy"
  }
}
variable "distribution_arn" { type = string }
variable "account_id" { type = string }
variable "environment" { type = string }
variable "secret_arn" {
  type = string
  validation {
    condition     = can(regex("^arn:aws:secretsmanager:us-east-1:${var.account_id}:secret:cybercoach/${var.environment}/origin-auth-[A-Za-z0-9]{6}$", var.secret_arn))
    error_message = "Exact environment origin credential metadata required at the wrapper boundary."
  }
}
variable "secret_kms_key_arn" { type = string }
variable "function_zip_path" { type = string }
variable "function_zip_sha256_base64" { type = string }
variable "custodian_role_arn" { type = string }
variable "api_execution_role_arn" { type = string }
module "origin_authentication" {
  providers = {
    aws                  = aws
    aws.origin_custodian = aws.origin_custodian
  }
  distribution_arn           = var.distribution_arn
  source                     = "../modules/origin-authentication"
  account_id                 = var.account_id
  environment                = var.environment
  secret_arn                 = var.secret_arn
  secret_kms_key_arn         = var.secret_kms_key_arn
  function_zip_path          = var.function_zip_path
  function_zip_sha256_base64 = var.function_zip_sha256_base64
  custodian_role_arn         = var.custodian_role_arn
  api_execution_role_arn     = var.api_execution_role_arn
}
output "binding" { value = module.origin_authentication.binding }
output "required_scoped_governance" { value = module.origin_authentication.required_scoped_governance }

sources.infra/aws/origin-bootstrap/main.tf:
# Ordinary metadata-only counterpart of origin-auth-launch.py bootstrap.
# This root owns credential-key policy throughout both phases; never a secret value or public route.
terraform {
  required_version = "= 1.11.2"
  required_providers { aws = { source = "hashicorp/aws", version = "= 6.50.0" } }
  backend "s3" {}
}

variable "account_id" {
  type     = string
  nullable = false
  validation {
    condition     = var.account_id == "564503811353"
    error_message = "Exact CyberCoach account required."
  }
}
variable "environment" {
  type     = string
  nullable = false
  validation {
    condition     = var.environment == "production"
    error_message = "This ordinary bootstrap root is production-only; existing DEV custody is unchanged."
  }
}
variable "operator_trust" {
  type     = string
  nullable = false
  validation {
    condition     = var.operator_trust == "mac-trusted-account-operators-v1"
    error_message = "Explicit existing trusted-account-operator decision required; this grants no additional principal."
  }
}

variable "credential_policy_phase" {
  type     = string
  default  = "initial"
  nullable = false
  validation {
    condition     = contains(["initial", "final"], var.credential_policy_phase)
    error_message = "Explicit initial or final credential policy phase required."
  }
}
variable "manage_secret_resource_policy" {
  type     = bool
  default  = false
  nullable = false
}
variable "prepare_final_key_policy" {
  description = "Install exact owned-key policy/metadata authority before selecting the final custodian key provider."
  type        = bool
  default     = false
  nullable    = false
}
variable "final_binding" {
  description = "Actual existing dedicated secret and immutable custodian/Lambda/API RoleIds; metadata only."
  type        = object({ secret_arn = string, custodian_role_id = string, lambda_role_id = string, api_role_id = string })
  default     = null
  validation {
    condition = var.final_binding == null ? true : (
      can(regex("^arn:aws:secretsmanager:us-east-1:564503811353:secret:cybercoach/production/origin-auth-[A-Za-z0-9]{6}$", var.final_binding.secret_arn)) &&
      alltrue([for id in [var.final_binding.custodian_role_id, var.final_binding.lambda_role_id, var.final_binding.api_role_id] : can(regex("^AROA[A-Z0-9]{17}$", id))]) &&
      length(toset([var.final_binding.custodian_role_id, var.final_binding.lambda_role_id, var.final_binding.api_role_id])) == 3
    )
    error_message = "Exact production secret and three distinct immutable role IDs required."
  }
}

locals {
  account          = "564503811353"
  region           = "us-east-1"
  name             = "cybercoach-production-origin-custodian"
  custodian_arn    = "arn:aws:iam::564503811353:role/platform-identities/production/cybercoach-production-origin-custodian"
  operator_arn     = "arn:aws:iam::564503811353:user/mclark"
  operator_user_id = "AIDAJ32SZWTZ33TRLYXEU"
  final_policy     = var.credential_policy_phase == "final"
  lambda_arn       = "arn:aws:iam::564503811353:role/cybercoach-origin-auth/production/cybercoach-production-origin-auth"
  api_arn          = "arn:aws:iam::564503811353:role/cybercoach/production/cybercoach-production-api-execution"
  metadata_readers = [local.operator_arn, "arn:aws:iam::564503811353:role/platform-foundation/public-frontdoor/production/cybercoach-production-foundation-public-frontdoor-plan", "arn:aws:iam::564503811353:role/platform-foundation/public-frontdoor/production/cybercoach-production-foundation-public-frontdoor-apply"]
  tags = {
    Project      = "CyberCoach"
    Environment  = "production"
    ManagedBy    = "OpenTofu"
    BillingOwner = "Mac Clark"
  }
}
provider "aws" {
  region              = local.region
  allowed_account_ids = [local.account]
  default_tags { tags = local.tags }
}
# Only the key provider changes identity. The existing state backend, role and
# secret metadata keep their original operator provider and resource addresses.
provider "aws" {
  alias               = "credential"
  region              = local.region
  allowed_account_ids = [local.account]
  default_tags { tags = local.tags }
  dynamic "assume_role" {
    for_each = local.final_policy ? [1] : []
    content {
      role_arn     = local.custodian_arn
      session_name = "cybercoach-origin-key-policy"
    }
  }
}
data "aws_caller_identity" "credential" { provider = aws.credential }
data "aws_iam_role" "lambda" {
  count = local.final_policy ? 1 : 0
  name  = "cybercoach-production-origin-auth"
}
data "aws_secretsmanager_secret" "final" {
  count = local.final_policy ? 1 : 0
  name  = "cybercoach/production/origin-auth"
}
data "aws_iam_role" "api" {
  count = local.final_policy ? 1 : 0
  name  = "cybercoach-production-api-execution"
}
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

resource "aws_iam_role" "custodian" {
  name                  = local.name
  path                  = "/platform-identities/production/"
  max_session_duration  = 3600
  force_detach_policies = false
  tags                  = local.tags
  assume_role_policy = jsonencode({ Version = "2012-10-17", Statement = [{
    Effect    = "Allow"
    Action    = "sts:AssumeRole"
    Principal = { AWS = local.operator_arn }
    Condition = { StringEquals = { "aws:userid" = local.operator_user_id } }
  }] })
  lifecycle {
    prevent_destroy = true
    precondition {
      condition     = data.aws_caller_identity.current.account_id == local.account && data.aws_caller_identity.current.arn == local.operator_arn && data.aws_caller_identity.current.user_id == local.operator_user_id && data.aws_region.current.region == local.region
      error_message = "Bootstrap requires the original mclark user ID in the exact account and us-east-1."
    }
    postcondition {
      condition     = self.arn == local.custodian_arn && can(regex("^AROA[A-Z0-9]{17}$", self.unique_id))
      error_message = "Exact created custodian ARN and immutable RoleId required."
    }
  }
}
resource "aws_kms_key" "credential" {
  provider                           = aws.credential
  description                        = "CyberCoach production dedicated origin credential"
  key_usage                          = "ENCRYPT_DECRYPT"
  customer_master_key_spec           = "SYMMETRIC_DEFAULT"
  is_enabled                         = true
  multi_region                       = false
  enable_key_rotation                = false
  deletion_window_in_days            = 30
  bypass_policy_lockout_safety_check = false
  tags                               = local.tags
  # One state owner, two explicit phases. No out-of-band PutKeyPolicy writer.
  policy = local.final_policy ? jsonencode({ Version = "2012-10-17", Statement = [
    { Sid = "DedicatedCustody", Effect = "Allow", Principal = { AWS = local.custodian_arn }, Action = "kms:*", Resource = "*" },
    { Sid = "ExactSecretReaders", Effect = "Allow", Principal = { AWS = sort([local.lambda_arn, local.api_arn]) }, Action = ["kms:Decrypt"], Resource = "*", Condition = { StringEquals = { "kms:ViaService" = "secretsmanager.us-east-1.amazonaws.com", "kms:EncryptionContext:SecretARN" = try(var.final_binding.secret_arn, "") } } },
    { Sid = "ExactAdmissionMetadata", Effect = "Allow", Principal = { AWS = sort(local.metadata_readers) }, Action = ["kms:GetKeyPolicy", "kms:ListGrants"], Resource = "*" }
    ] }) : jsonencode({ Version = "2012-10-17", Statement = [{
      Sid       = "DedicatedCustody", Effect = "Allow", Principal = { AWS = "arn:aws:iam::564503811353:root" }, Action = "kms:*", Resource = "*",
      Condition = { ArnEquals = { "aws:PrincipalArn" = [local.custodian_arn, local.operator_arn] } }
  }] })
  depends_on = [aws_iam_role.custodian]
  lifecycle {
    prevent_destroy = true
    precondition {
      condition     = local.final_policy ? (var.final_binding != null && var.manage_secret_resource_policy && var.prepare_final_key_policy) : var.final_binding == null
      error_message = "Final phase requires real bindings and installed policy-manager selection; initial phase rejects final bindings."
    }
    precondition {
      condition = local.final_policy ? try(
        data.aws_caller_identity.credential.account_id == local.account &&
        data.aws_caller_identity.credential.arn == "arn:aws:sts::564503811353:assumed-role/${local.name}/cybercoach-origin-key-policy" &&
        data.aws_caller_identity.credential.user_id == "${var.final_binding.custodian_role_id}:cybercoach-origin-key-policy" &&
        aws_iam_role.custodian.unique_id == var.final_binding.custodian_role_id &&
        data.aws_secretsmanager_secret.final[0].arn == var.final_binding.secret_arn &&
        data.aws_secretsmanager_secret.final[0].name == "cybercoach/production/origin-auth" &&
        data.aws_iam_role.lambda[0].arn == local.lambda_arn && data.aws_iam_role.lambda[0].unique_id == var.final_binding.lambda_role_id &&
        data.aws_iam_role.api[0].arn == local.api_arn && data.aws_iam_role.api[0].unique_id == var.final_binding.api_role_id, false
      ) : (data.aws_caller_identity.credential.account_id == local.account && data.aws_caller_identity.credential.arn == local.operator_arn && data.aws_caller_identity.credential.user_id == local.operator_user_id)
      error_message = "Actual phase-specific key caller and exact original custodian/two reader identities required."
    }
    postcondition {
      condition     = can(regex("^arn:aws:kms:us-east-1:564503811353:key/[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$", self.arn))
      error_message = "Dedicated same-account us-east-1 credential key required."
    }
  }
}
resource "aws_secretsmanager_secret" "origin" {
  name                           = "cybercoach/production/origin-auth"
  kms_key_id                     = aws_kms_key.credential.arn
  recovery_window_in_days        = 30
  force_overwrite_replica_secret = false
  tags                           = local.tags
  lifecycle {
    prevent_destroy = true
    postcondition {
      condition     = !local.final_policy || try(self.arn == var.final_binding.secret_arn, false)
      error_message = "Final policy must reference this same owned secret, never another container."
    }
    postcondition {
      condition     = can(regex("^arn:aws:secretsmanager:us-east-1:564503811353:secret:cybercoach/production/origin-auth-[A-Za-z0-9]{6}$", self.arn))
      error_message = "Exact production origin secret metadata required."
    }
  }
}

# Install before the authenticator alias assumes this role. This is not a
# credential read grant and never owns the secret resource-policy body itself.
resource "aws_iam_role_policy" "secret_policy_manager" {
  count = var.manage_secret_resource_policy ? 1 : 0
  role  = aws_iam_role.custodian.id
  name  = "exact-origin-secret-policy-management"
  policy = jsonencode({ Version = "2012-10-17", Statement = [{
    Effect = "Allow", Action = ["secretsmanager:GetResourcePolicy", "secretsmanager:PutResourcePolicy"], Resource = [aws_secretsmanager_secret.origin.arn]
  }] })
  lifecycle { prevent_destroy = true }
}

resource "aws_iam_role_policy" "key_policy_manager" {
  count = var.prepare_final_key_policy ? 1 : 0
  role  = aws_iam_role.custodian.id
  name  = "exact-origin-key-policy-management"
  policy = jsonencode({ Version = "2012-10-17", Statement = [{
    Effect   = "Allow"
    Action   = ["kms:DescribeKey", "kms:GetKeyPolicy", "kms:GetKeyRotationStatus", "kms:ListResourceTags", "kms:PutKeyPolicy"]
    Resource = [aws_kms_key.credential.arn]
  }] })
  lifecycle { prevent_destroy = true }
}

output "metadata" {
  description = "Resource identities only; this output is not a credential initialization, final custody, or public admission receipt."
  value = {
    account_id            = local.account
    region                = local.region
    environment           = var.environment
    operator_trust        = var.operator_trust
    custodian_arn         = aws_iam_role.custodian.arn
    custodian_role_id     = aws_iam_role.custodian.unique_id
    secret_arn            = aws_secretsmanager_secret.origin.arn
    secret_kms_key_arn    = aws_kms_key.credential.arn
    secret_value_managed  = false
    public_enable_managed = false
    custody_stage         = local.final_policy ? "final-key-policy-only" : "initial-metadata-only"
  }
}

sources.infra/aws/public-frontdoor/main.tf:
terraform {
  required_version = "= 1.11.2"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 6.50.0"
    }
  }
  backend "s3" {}
}
provider "aws" {
  region              = var.region
  allowed_account_ids = [var.account_id]
  default_tags { tags = merge({ Project = "CyberCoach", Environment = var.environment, ManagedBy = "OpenTofu" }, var.environment == "production" ? { BillingOwner = "Mac Clark" } : {}) }
}
provider "aws" {
  alias               = "edge"
  region              = "us-east-1"
  allowed_account_ids = [var.account_id]
  default_tags { tags = merge({ Project = "CyberCoach", Environment = var.environment, ManagedBy = "OpenTofu" }, var.environment == "production" ? { BillingOwner = "Mac Clark" } : {}) }
}
# Only metadata for the exact accepted log keys uses its existing installer identity.
# Every public resource and the backend retain their original caller.
locals {
  access_log_metadata_profile = (
    var.environment == "dev" && var.account_id == "564503811353" &&
    var.access_logs.kms_key_arn == "arn:aws:kms:us-east-1:564503811353:key/f87660a7-cd55-4e04-8a57-89de5979e9c9" &&
    var.access_logs.custodian_role_arn == "arn:aws:iam::564503811353:role/platform-identities/dev/cybercoach-dev-public-log-installer"
  ) ? "cybercoach-dev-public-log-installer-r2" : null
  access_log_metadata_role_arn = (
    var.environment == "production" && var.account_id == "564503811353" &&
    var.access_logs.kms_key_arn == "arn:aws:kms:us-east-1:564503811353:key/766eb3bc-36a4-4ab5-a6ed-651bc465db63" &&
    var.access_logs.custodian_role_arn == "arn:aws:iam::564503811353:role/platform-identities/production/cybercoach-production-public-log-installer"
  ) ? var.access_logs.custodian_role_arn : null
}
provider "aws" {
  alias               = "log_metadata"
  region              = "us-east-1"
  allowed_account_ids = [var.account_id]
  profile             = local.access_log_metadata_profile
  dynamic "assume_role" {
    for_each = local.access_log_metadata_role_arn == null ? [] : [local.access_log_metadata_role_arn]
    content {
      role_arn     = assume_role.value
      session_name = "cybercoach-prod-public-log-r1"
      duration     = "15m"
    }
  }
}
variable "account_id" {
  type = string
  validation {
    condition     = can(regex("^[0-9]{12}$", var.account_id))
    error_message = "Use the reviewed numeric account."
  }
}
variable "region" {
  type = string
  validation {
    # Deliberately bounded supported subset; adding another region needs review.
    condition     = contains(["us-east-1", "us-east-2", "us-west-1", "us-west-2"], var.region)
    error_message = "This contract supports only reviewed US commercial VPC-origin regions."
  }
}
variable "environment" {
  type = string
  validation {
    condition     = contains(["dev", "production"], var.environment)
    error_message = "Use dev or production."
  }
}
variable "origin" {
  description = "Exact runtime public_frontdoor_origin output, checked against provider observations."
  type = object({
    account_id                  = string, region = string, environment = string, hostname = string,
    authority_sha256            = string, vpc_id = string, subnet_ids = set(string), alb_arn = string,
    edge_security_group_id      = string, readiness_alb_security_group_id = string,
    readiness_security_group_id = string, certificate_arn = string, listener_arn = string,
    origin_authentication       = optional(string, "none")
  })
  validation {
    condition     = length(var.origin.hostname) <= 253 && var.origin.account_id == var.account_id && var.origin.region == var.region && var.origin.environment == var.environment && can(regex("^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z]{2,63}$", var.origin.hostname)) && can(regex("^[a-f0-9]{64}$", var.origin.authority_sha256)) && can(regex("^arn:aws:elasticloadbalancing:${var.region}:${var.account_id}:loadbalancer/app/cybercoach-${var.environment}/[a-z0-9]+$", var.origin.alb_arn)) && can(regex("^arn:aws:acm:${var.region}:${var.account_id}:certificate/[a-f0-9-]{36}$", var.origin.certificate_arn)) && length(var.origin.subnet_ids) >= 2 && length(toset([var.origin.edge_security_group_id, var.origin.readiness_alb_security_group_id, var.origin.readiness_security_group_id])) == 3
    error_message = "Origin must bind the exact environment, account, region, canonical host, regional certificate and distinct private groups."
  }
}
variable "edge_certificate_arn" {
  type = string
  validation {
    condition     = can(regex("^arn:aws:acm:us-east-1:${var.account_id}:certificate/[a-f0-9-]{36}$", var.edge_certificate_arn))
    error_message = "Viewer TLS requires this account's approved us-east-1 ACM certificate."
  }
}
variable "authority" {
  description = "External reviewed effective-policy receipt. Freeform input/digest is a binding, not proof of reviewer authenticity or deployed IAM. Protected workflow must authenticate it before apply."
  type = object({
    audience                                  = string, account_id = string, region = string, environment = string,
    hostname                                  = string, alb_arn = string, vpc_id = string, subnet_ids = set(string),
    distribution_name                         = string, evidence_sha256 = string,
    exclusive_origin_and_distribution_control = bool, sharing_denied = bool,
    origin_active_confirmed                   = bool, origin_read_timeout_110_approved = bool
  })
  validation {
    condition     = var.authority.audience == "public" && var.authority.account_id == var.account_id && var.authority.region == var.region && var.authority.environment == var.environment && var.authority.hostname == var.origin.hostname && var.authority.alb_arn == var.origin.alb_arn && var.authority.vpc_id == var.origin.vpc_id && var.authority.subnet_ids == var.origin.subnet_ids && var.authority.distribution_name == "cybercoach-${var.environment}-public" && var.authority.evidence_sha256 == var.origin.authority_sha256 && (contains(["allocate", "dns-only"], var.origin_auth_stage) || var.origin.origin_authentication == "lambda-token-v1" ? (!var.authority.exclusive_origin_and_distribution_control && !var.authority.sharing_denied) : (var.authority.exclusive_origin_and_distribution_control && var.authority.sharing_denied)) && var.authority.origin_active_confirmed && var.authority.origin_read_timeout_110_approved
    error_message = "Exact public audience and active-origin/110-second authority required. Origin-auth mode disclaims network exclusivity and requires protected consumer admission; legacy mode retains both exclusions."
  }
}
variable "enabled" {
  description = "Explicit reviewed distribution activation. Default creates a disabled distribution; never opens admission."
  type        = bool
  default     = false
}
variable "waf_rate_limit" {
  type = number
  validation {
    condition     = var.waf_rate_limit >= 10 && var.waf_rate_limit <= 2000000000 && floor(var.waf_rate_limit) == var.waf_rate_limit
    error_message = "Supply an explicitly reviewed integral per-viewer five-minute rate limit."
  }
}

module "public_frontdoor" {
  source                 = "../modules/public-frontdoor"
  origin_auth_stage      = var.origin_auth_stage
  origin_auth_lambda_arn = var.origin_auth_lambda_arn
  access_logs            = var.access_logs
  providers              = { aws = aws, aws.edge = aws.edge, aws.log_metadata = aws.log_metadata }
  account_id             = var.account_id
  region                 = var.region
  environment            = var.environment
  origin                 = var.origin
  edge_certificate_arn   = var.edge_certificate_arn
  authority              = var.authority
  enabled                = var.enabled
  waf_rate_limit         = var.waf_rate_limit
  waf_auth_rate_limit    = var.waf_auth_rate_limit
  dev_network_policy     = var.dev_network_policy
}
output "distribution" { value = module.public_frontdoor.distribution }

variable "waf_auth_rate_limit" {
  type = number
  validation {
    condition     = var.waf_auth_rate_limit >= 10 && var.waf_auth_rate_limit <= var.waf_rate_limit && floor(var.waf_auth_rate_limit) == var.waf_auth_rate_limit
    error_message = "Supply an explicit authentication viewer limit no larger than the general limit."
  }
}

output "execution" { value = module.public_frontdoor.execution }

variable "access_logs" {
  description = "Required independently installed same-account us-east-1 log custody; values bind acceptance, not proof of it."
  type        = object({ log_group_arn = string, kms_key_arn = string, retention_days = number, custodian_role_arn = string })
  nullable    = false
  validation {
    condition     = var.access_logs.log_group_arn == "arn:aws:logs:us-east-1:${var.account_id}:log-group:cybercoach-${var.environment}-public-access" && can(regex("^arn:aws:kms:us-east-1:${var.account_id}:key/[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$", var.access_logs.kms_key_arn)) && contains([1, 3, 5, 7, 14, 30, 60, 90], var.access_logs.retention_days) && can(regex("^arn:aws:iam::${var.account_id}:role/platform-identities/${var.environment}/[A-Za-z0-9+=,.@_-]+$", var.access_logs.custodian_role_arn))
    error_message = "Exact public log group, same-account us-east-1 customer key, explicit bounded retention, and independent environment custodian required."
  }
}

output "access_logging" { value = module.public_frontdoor.access_logging }

variable "origin_auth_lambda_arn" {
  description = "Optional exact independently custodied versioned origin authenticator. Null preserves the legacy held topology; ARN alone is not acceptance."
  validation {
    condition     = contains(["none", "lambda-token-v1"], var.origin.origin_authentication) && ((var.origin_auth_lambda_arn == null) == (var.origin.origin_authentication == "none"))
    error_message = "Origin authenticator association and runtime authentication must be selected together."
  }
  type    = string
  default = null
  validation {
    condition     = var.origin_auth_lambda_arn == null ? true : can(regex("^arn:aws:lambda:us-east-1:${var.account_id}:function:cybercoach-${var.environment}-origin-auth:[1-9][0-9]*$", var.origin_auth_lambda_arn))
    error_message = "Only this environment's exact origin authenticator is supported."
  }
}

variable "origin_auth_stage" {
  description = "Source-verified Mac origin-auth launch stage. Allocation is disabled and carries no credential association."
  type        = string
  default     = "legacy"
  validation {
    condition     = contains(["legacy", "allocate", "associate", "enable", "dns-only"], var.origin_auth_stage) && (var.origin_auth_stage != "allocate" || (!var.enabled && var.origin_auth_lambda_arn == null && var.origin.origin_authentication == "none")) && (var.origin_auth_stage != "associate" || (!var.enabled && var.origin_auth_lambda_arn != null)) && (var.origin_auth_stage != "enable" || (var.enabled && var.origin_auth_lambda_arn != null))
    error_message = "Allocation is disabled and unauthenticated; association stays disabled; only explicit enable stage activates the bound authenticator."
  }
  validation {
    condition = var.origin_auth_stage != "dns-only" || (
      var.account_id == "564503811353" && var.region == "us-east-1" &&
      var.environment == "production" && var.origin.hostname == "cybercoach.nc.gov" &&
      var.enabled && var.origin_auth_lambda_arn == null && var.origin.origin_authentication == "none"
    )
    error_message = "DNS-only enables only the NC production distribution behind default-block WAF; it cannot assert origin authentication or application acceptance."
  }
}

variable "dev_network_policy" {
  description = "DEV-only copy of the reviewed nonproduction global source-IP allowlists. Null preserves the existing unrestricted audience. No host, header, route or arbitrary CIDR exceptions."
  type        = string
  default     = null
  validation {
    condition     = var.dev_network_policy == null ? true : (var.environment == "dev" && var.dev_network_policy == "nonprod-global-20260925")
    error_message = "Only DEV may select the exact reviewed nonprod-global-20260925 policy snapshot."
  }
}

output "dev_network_policy" { value = module.public_frontdoor.dev_network_policy }
